// ─── Spy wrapper that records calls ──────────────────────────────────────────

function spyOn<T extends (...a: any[]) => any>(fn: T): T & { calls: Parameters<T>[] } {
  const calls: Parameters<T>[] = [];
  const spy = ((...args: Parameters<T>) => { calls.push(args); return fn(...args); }) as T & { calls: Parameters<T>[] };
  spy.calls = calls;
  return spy;
}

