/**
 * gdprErasure.ts — POST /api/v1/gdpr/erase
 *
 * Exposes the GDPR erasure orchestrator as an HTTP endpoint.
 *
 * ## Security
 *
 * - Requires `x-chronopay-user-id` + `x-chronopay-role` headers.
 * - Only `admin` role may trigger live erasure.
 * - `auditor` role may use `dryRun: true` only; live erasure returns 403.
 *
 * ## Request body
 *
 * ```json
 * { "subjectId": "<uuid>", "dryRun": false }
 * ```
 *
 * `dryRun` defaults to `false`.
 *
 * ## Response (200 OK)
 *
 * ```json
 * {
 *   "success": true,
 *   "receipt": { ... },
 *   "plan": [ ... ]   // only present when dryRun is true
 * }
 * ```
 *
 * ## Error responses
 *
 * | Status | Reason                                              |
 * |--------|-----------------------------------------------------|
 * | 400    | Missing or invalid `subjectId`                      |
 * | 403    | Auditor attempting a live erasure                   |
 * | 409    | Subject is under a legal hold                       |
 * | 500    | Unexpected server error                             |
 */

import { Router, type Request, type Response } from "express";
import { requireAuthenticatedActor } from "../middleware/auth.js";
import { createAuthAwareRateLimiter } from "../middleware/rateLimiter.js";
import {
  GdprErasureOrchestrator,
  LegalHoldViolationError,
} from "../services/gdprErasure/GdprErasureOrchestrator.js";
import type { ErasureEventLog } from "../services/gdprErasure/eventLog.js";
import type { DbPool, LegalHoldChecker } from "../services/gdprErasure/GdprErasureOrchestrator.js";
import { AuditLogger } from "../services/auditLogger.js";

export interface GdprErasureRouterOptions {
  /** Override for testing — replaces the real DB pool. */
  pool?: DbPool;
  /** Override for testing — replaces the real legal-hold checker. */
  legalHold?: LegalHoldChecker;
  /** Override for testing — replaces the real audit logger. */
  auditLogger?: AuditLogger;
  /** Override for testing — replaces the real event log. */
  eventLog?: ErasureEventLog;
}

/**
 * Factory that creates the erasure router with optional injected dependencies.
 */
export function createGdprErasureRouter(opts?: GdprErasureRouterOptions): Router {
  const router = Router();
  const orchestrator = new GdprErasureOrchestrator({
    pool: opts?.pool,
    legalHold: opts?.legalHold,
    auditLogger: opts?.auditLogger,
    eventLog: opts?.eventLog,
  });

  /**
   * POST /
   *
   * Erase (or dry-run preview) PII for the given `subjectId`.
   * Access: admin (live + dry-run), auditor (dry-run only).
   */
  router.post(
    "/",
    requireAuthenticatedActor(["admin", "auditor"]),
    createAuthAwareRateLimiter(),
    async (req: Request, res: Response) => {
      try {
        const { subjectId, dryRun = false } = req.body as {
          subjectId?: unknown;
          dryRun?: unknown;
        };

        // ── Input validation ──────────────────────────────────────────────────
        if (!subjectId || typeof subjectId !== "string" || !subjectId.trim()) {
          return res.status(400).json({
            success: false,
            error: "subjectId is required and must be a non-empty string.",
          });
        }

        const isDryRun = dryRun === true || dryRun === "true";

        // ── Role enforcement ──────────────────────────────────────────────────
        // Auditors may only use dry-run mode.
        const actorRole = req.auth?.role;
        if (actorRole === "auditor" && !isDryRun) {
          return res.status(403).json({
            success: false,
            error: "Auditors may only perform dry-run erasure previews.",
          });
        }

        const requestedBy = req.auth?.userId ?? "unknown";

        const result = await orchestrator.erase({
          subjectId: subjectId.trim(),
          requestedBy,
          dryRun: isDryRun,
        });

        const responseBody: Record<string, unknown> = {
          success: true,
          receipt: result.receipt,
        };

        // Include the action plan in dry-run responses for auditor review.
        if (isDryRun) {
          responseBody.plan = result.tableResults.map((t) => ({
            table: t.table,
            plannedActions: t.actions,
          }));
        }

        return res.status(200).json(responseBody);
      } catch (error) {
        if (error instanceof LegalHoldViolationError) {
          return res.status(409).json({
            success: false,
            error: error.message,
            code: "LEGAL_HOLD",
          });
        }

        const message = error instanceof Error ? error.message : "Erasure failed";
        return res.status(500).json({ success: false, error: message });
      }
    },
  );

  return router;
}

/** Default router instance (uses real DB + real services). */
export const gdprErasureRouter = createGdprErasureRouter();

/**
 * Unit tests for the DSR SLA scheduler worker.
 *
 * No real DB, file system, or live timers are used.
 * All side-effects go through injected fakes.
 */

import {
  runCycle,
  runOnce,
  DsrSlaWorker,
  type DsrAlertPayload,
  type AlertFn,
} from "../dsrSlaWorker.js";
import { ALERT_THRESHOLDS, type DsrRecord } from "../../services/dsrSlaService.js";
import type { AuditLogger } from "../../services/auditLogger.js";

// ─── Helpers ──────────────────────────────────────────────────────────────────

const SILENT_LOGGER = { log: () => Promise.resolve() } as unknown as AuditLogger;

function makeRecord(overrides: Partial<DsrRecord> = {}): DsrRecord {
  const now = new Date("2025-06-01T00:00:00Z");
  const dueAt = new Date("2025-06-08T00:00:00Z");
  return {
    id: "dsr-001", subjectId: "user-1", subjectEmail: "alice@example.com",
    requestType: "access", receivedAt: now, dueAt, status: "open",
    extensionReason: null, alert7dSent: false, alert3dSent: false, alert1dSent: false,
    resolvedAt: null, resolvedBy: null, resolutionReason: null, resolutionEvidence: null,
    notes: null, createdAt: now, updatedAt: now, daysRemaining: 7,
    msRemaining: 7 * 24 * 60 * 60 * 1000, ...overrides,
  };
}

/** Minimal spy — records calls, resolves with undefined by default. */
function makeSpy<T extends unknown[] = unknown[], R = void>(
  impl?: (...args: T) => Promise<R>,
) {
  const calls: T[] = [];
  const errors: Error[] = [];
  let callIndex = 0;
  const fn = async (...args: T): Promise<R> => {
    calls.push(args);
    if (errors[callIndex] !== undefined) {
      const err = errors[callIndex++];
      throw err;
    }
    callIndex++;
    return impl ? impl(...args) : (undefined as unknown as R);
  };
  fn.calls = calls;
  fn.mockRejectedValueOnce = (err: Error) => { errors[calls.length] = err; };
  return fn;
}

function makeMockService(pendingByThreshold: Partial<Record<number, DsrRecord[]>> = {}) {
  const findPendingAlertsCalls: [number, Date][] = [];
  const markAlertSentCalls: [string, number][] = [];

  return {
    findPendingAlerts: async (threshold: number, now: Date) => {
      findPendingAlertsCalls.push([threshold, now]);
      return pendingByThreshold[threshold] ?? [];
    },
    markAlertSent: async (id: string, threshold: number) => {
      markAlertSentCalls.push([id, threshold]);
    },
    _findPendingAlertsCalls: findPendingAlertsCalls,
    _markAlertSentCalls: markAlertSentCalls,
  } as any;
}

// ─── runCycle ─────────────────────────────────────────────────────────────────

describe("runCycle", () => {
  it("returns zero counts when no alerts are pending", async () => {
    const svc = makeMockService();
    const fired: DsrAlertPayload[] = [];
    const alertFn: AlertFn = async (p) => { fired.push(p); };

    const result = await runCycle(svc, alertFn, new Date());

    expect(result.alertsFired).toBe(0);
    expect(result.errors).toBe(0);
    expect(fired).toHaveLength(0);
  });

  it("fires an alert and calls markAlertSent for each pending record", async () => {
    const record = makeRecord({ id: "dsr-7d", daysRemaining: 7 });
    const svc = makeMockService({ 7: [record] });
    const fired: DsrAlertPayload[] = [];
    const alertFn: AlertFn = async (p) => { fired.push(p); };

    const result = await runCycle(svc, alertFn, new Date());

    expect(result.alertsFired).toBe(1);
    expect(result.byThreshold[7].fired).toBe(1);
    expect(fired).toHaveLength(1);
    expect(svc._markAlertSentCalls).toContainEqual(["dsr-7d", 7]);
  });

  it("fires alerts across all three thresholds independently", async () => {
    const svc = makeMockService({
      7: [makeRecord({ id: "dsr-7d" })],
      3: [makeRecord({ id: "dsr-3d" })],
      1: [makeRecord({ id: "dsr-1d" })],
    });
    const fired: DsrAlertPayload[] = [];
    const alertFn: AlertFn = async (p) => { fired.push(p); };

    const result = await runCycle(svc, alertFn, new Date());

    expect(result.alertsFired).toBe(3);
    expect(result.byThreshold[7].fired).toBe(1);
    expect(result.byThreshold[3].fired).toBe(1);
    expect(result.byThreshold[1].fired).toBe(1);
    expect(svc._markAlertSentCalls).toHaveLength(3);
  });

  it("builds the correct alert payload", async () => {
    const dueAt = new Date("2025-06-08T00:00:00Z");
    const record = makeRecord({ id: "dsr-abc", daysRemaining: 7, dueAt });
    const svc = makeMockService({ 7: [record] });
    const payloads: DsrAlertPayload[] = [];
    const alertFn: AlertFn = async (p) => { payloads.push(p); };

    await runCycle(svc, alertFn, new Date("2025-06-01T00:00:00Z"));

    expect(payloads[0].dsrId).toBe("dsr-abc");
    expect(payloads[0].subjectId).toBe("user-1");
    expect(payloads[0].requestType).toBe("access");
    expect(payloads[0].dueAt).toEqual(dueAt);
    expect(payloads[0].daysRemaining).toBe(7);
    expect(payloads[0].threshold).toBe(7);
  });

  it("does NOT call markAlertSent when alertFn throws", async () => {
    const svc = makeMockService({ 7: [makeRecord({ id: "dsr-err" })] });
    const alertFn: AlertFn = async () => { throw new Error("channel down"); };

    const result = await runCycle(svc, alertFn, new Date());

    expect(result.errors).toBe(1);
    expect(result.alertsFired).toBe(0);
    expect(svc._markAlertSentCalls).toHaveLength(0);
  });

  it("continues processing remaining records after one alertFn failure", async () => {
    const records = [
      makeRecord({ id: "dsr-fail" }),
      makeRecord({ id: "dsr-ok" }),
    ];
    const svc = makeMockService({ 7: records });
    let callCount = 0;
    const alertFn: AlertFn = async () => {
      if (callCount++ === 0) throw new Error("first fails");
    };

    const result = await runCycle(svc, alertFn, new Date());

    expect(result.alertsFired).toBe(1);
    expect(result.errors).toBe(1);
    expect(svc._markAlertSentCalls).toContainEqual(["dsr-ok", 7]);
