describe("DsrSlaService edge cases", () => {
  describe("weekend / month-boundary rollover", () => {
    it("Jan 31 + 30 days => Mar 2 (non-leap year)", async () => {
      const receivedAt = new Date("2025-01-31T00:00:00Z");
      const row = makeRow();
      const { queryFn, calls } = makeSpyQueryFn(makeQueryFn([row]));
      const svc = makeService(queryFn);

      await svc.create({ subjectId: "u", subjectEmail: "u@e.com", requestType: "access", receivedAt });

      const dueAt = new Date(calls[0].params![4] as string);
      expect(dueAt.toISOString().startsWith("2025-03-02")).toBe(true);
    });

    it("Feb 28 + 30 days => Mar 30 (non-leap year)", async () => {
      const receivedAt = new Date("2025-02-28T00:00:00Z");
      const row = makeRow();
      const { queryFn, calls } = makeSpyQueryFn(makeQueryFn([row]));
      const svc = makeService(queryFn);

      await svc.create({ subjectId: "u", subjectEmail: "u@e.com", requestType: "erasure", receivedAt });

      const dueAt = new Date(calls[0].params![4] as string);
      expect(dueAt.toISOString().startsWith("2025-03-30")).toBe(true);
    });

    it("Feb 28 + 30 days => Mar 29 in a leap year", async () => {
      const receivedAt = new Date("2024-02-28T00:00:00Z"); // 2024 is a leap year
      const row = makeRow();
      const { queryFn, calls } = makeSpyQueryFn(makeQueryFn([row]));
      const svc = makeService(queryFn);

      await svc.create({ subjectId: "u", subjectEmail: "u@e.com", requestType: "erasure", receivedAt });

      const dueAt = new Date(calls[0].params![4] as string);
      expect(dueAt.toISOString().startsWith("2024-03-29")).toBe(true);
    });
  });

  describe("clock skew tolerance", () => {
    it("daysRemaining is computed from the injected now, not system clock", async () => {
      // If the clock were wrong by 2 days this test would still pass because
      // we inject an explicit 'now' to both the row and the method.
      const now = new Date("2025-06-10T00:00:00Z");
      const dueAt = new Date("2025-06-13T00:00:00Z");
      const row = makeRow({ due_at: dueAt.toISOString() });
      const svc = makeService(makeQueryFn([row]));

      const record = await svc.findById("dsr-001", now);
      expect(record!.daysRemaining).toBe(3);
    });
  });

  describe("request reopened", () => {
    it("resets all three alert flags to false so alerts re-fire", async () => {
      const row = makeRow({
        status: "open",
        alert_7d_sent: false,
        alert_3d_sent: false,
        alert_1d_sent: false,
      });
      const { queryFn, calls } = makeSpyQueryFn(makeQueryFn([row]));
      const svc = makeService(queryFn);

      await svc.reopen("dsr-001", "Regulatory challenge");

      // The UPDATE should set all three flags to FALSE
      expect(calls[0].text).toContain("alert_7d_sent       = FALSE");
      expect(calls[0].text).toContain("alert_3d_sent       = FALSE");
      expect(calls[0].text).toContain("alert_1d_sent       = FALSE");
    });
  });
});

/**
 * Tests for #472 – refundable-hold visibility filter.
 *
 * Verifies that:
 *  - suppressHeld=true (default) excludes slots with active holds
 *  - suppressHeld=false shows held slots
 *  - showHeldReleaseEta=true attaches heldReleaseEta when suppressHeld=false
 *  - policy toggle (showHeldReleaseEta) does not leak ETA when suppressHeld=true
 */

import { describe, it, expect, beforeEach } from "@jest/globals";
import { MarketplaceSearchService } from "../marketplaceSearchService.js";
import { MarketplaceSearchQuery } from "../../validation/marketplaceSearchSchema.js";

const NOW_ISO = new Date("2026-07-28T12:00:00Z").toISOString();
const HOLD_EXPIRES_ISO = new Date("2026-07-28T13:00:00Z").toISOString();

// ─── Minimal mock pool ────────────────────────────────────────────────────────

type MockRow = {
  id: number;
  professional_id: string;
  start_time: string;
  end_time: string;
  category: string;
  price_cents: number;
  supplier_rating: number;
  status: string;
  created_at: string;
  held_release_eta?: string | null;
};

class MockPool {
  public rows: MockRow[] = [];
  public lastSql = "";
  public lastParams: unknown[] = [];

  async query(sql: string, params: unknown[] = []): Promise<{ rows: unknown[] }> {
    this.lastSql = sql;
    this.lastParams = params;

    if (sql.includes("COUNT(*)")) {
      const visible = this.visibleRows(sql);
      return { rows: [{ total: String(visible.length) }] };
    }

    const visible = this.visibleRows(sql);
    return { rows: visible };
  }

  /** Simulate the NOT EXISTS / suppression filter the real DB would apply. */
  private visibleRows(sql: string): MockRow[] {
    const suppressHeld = sql.includes("NOT EXISTS");
    return this.rows.filter((r) => {
      if (suppressHeld) {
        // Simulate: row is hidden when it is held (held_release_eta is set)
        return r.held_release_eta == null;
      }
      return true;
    });
  }
}

// ─── Test helpers ─────────────────────────────────────────────────────────────

function makeQuery(overrides: Partial<MarketplaceSearchQuery> = {}): MarketplaceSearchQuery {
  return {
    page: 1,
    limit: 10,
    sortBy: "relevance",
    suppressHeld: true,
    showHeldReleaseEta: false,
    ...overrides,
  };
}

function makeAvailableRow(id: number): MockRow {
  return {
    id,
    professional_id: `pro-${id}`,
    start_time: "2026-08-01T09:00:00Z",
    end_time: "2026-08-01T10:00:00Z",
    category: "consulting",
    price_cents: 5000,
    supplier_rating: 4.2,
    status: "available",
    created_at: "2026-07-01T00:00:00Z",
    held_release_eta: null,
  };
}

function makeHeldRow(id: number): MockRow {
  return {
    ...makeAvailableRow(id),
    held_release_eta: HOLD_EXPIRES_ISO,
  };
}

// ─── Tests ────────────────────────────────────────────────────────────────────

describe("MarketplaceSearchService – hold visibility filter (#472)", () => {
  let pool: MockPool;
  let service: MarketplaceSearchService;

  beforeEach(() => {
    pool = new MockPool();
    service = new MarketplaceSearchService(pool as any);
  });

  it("default: suppressHeld=true excludes held slots from results", async () => {
    pool.rows = [makeAvailableRow(1), makeHeldRow(2), makeAvailableRow(3)];

    const result = await service.search(makeQuery({ suppressHeld: true }));

    expect(result.slots).toHaveLength(2);
    expect(result.slots.map((s) => s.id)).toEqual([1, 3]);
  });

  it("suppressHeld=true emits NOT EXISTS predicate in SQL", async () => {
    pool.rows = [makeAvailableRow(1)];
    await service.search(makeQuery({ suppressHeld: true }));

    expect(pool.lastSql).toContain("NOT EXISTS");
    expect(pool.lastSql).toContain("slot_holds");
    expect(pool.lastSql).toContain("released_at IS NULL");
    expect(pool.lastSql).toContain("expires_at > NOW()");
  });

  it("suppressHeld=false does NOT emit NOT EXISTS predicate", async () => {
    pool.rows = [makeAvailableRow(1), makeHeldRow(2)];
    await service.search(makeQuery({ suppressHeld: false, showHeldReleaseEta: false }));

    expect(pool.lastSql).not.toContain("NOT EXISTS");
  });

  it("suppressHeld=false returns held and available slots", async () => {
    pool.rows = [makeAvailableRow(1), makeHeldRow(2)];

    const result = await service.search(makeQuery({ suppressHeld: false, showHeldReleaseEta: false }));

    expect(result.slots).toHaveLength(2);
  });

  it("showHeldReleaseEta=true with suppressHeld=false includes held_release_eta subquery", async () => {
    pool.rows = [makeHeldRow(10)];
    await service.search(makeQuery({ suppressHeld: false, showHeldReleaseEta: true }));

    expect(pool.lastSql).toContain("held_release_eta");
  });

  it("showHeldReleaseEta=true with suppressHeld=true does NOT include ETA subquery (slots are not returned)", async () => {
    pool.rows = [makeAvailableRow(1)];
    await service.search(makeQuery({ suppressHeld: true, showHeldReleaseEta: true }));

    // suppressHeld=true means held slots are already excluded; no ETA column needed
    expect(pool.lastSql).not.toContain("held_release_eta");
  });

  it("showHeldReleaseEta=false with suppressHeld=false omits ETA subquery", async () => {
    pool.rows = [makeHeldRow(5)];
    await service.search(makeQuery({ suppressHeld: false, showHeldReleaseEta: false }));

    expect(pool.lastSql).not.toContain("held_release_eta");
  });

  it("returns total count excluding held slots when suppressHeld=true", async () => {
    pool.rows = [makeAvailableRow(1), makeHeldRow(2), makeHeldRow(3)];

    const result = await service.search(makeQuery({ suppressHeld: true }));

    expect(result.total).toBe(1);
  });

  it("returns total count including held slots when suppressHeld=false", async () => {
    pool.rows = [makeAvailableRow(1), makeHeldRow(2), makeHeldRow(3)];

    const result = await service.search(makeQuery({ suppressHeld: false }));

    expect(result.total).toBe(3);
  });
});

/**
 * Tests for #478 – partial-refund approval workflow with threshold check and audit.
 */

import { describe, it, expect, beforeEach } from "@jest/globals";
import {
  PartialRefundApprovalService,
  RefundApprovalError,
  DEFAULT_THRESHOLDS,
} from "../partialRefundApprovalService.js";
import { CreateRefundRequest } from "../../types/refund.js";
import { AuditLogger } from "../auditLogger.js";

// ─── Helpers ──────────────────────────────────────────────────────────────────

function makeRequest(overrides: Partial<CreateRefundRequest> = {}): CreateRefundRequest {
  return {
    paymentId: "pay-001",
    amountCents: 500_00, // $500 – below $10,000 threshold
    currency: "USD",
    reason: "customer complaint",
    refundedBy: "admin-a",
    ...overrides,
  };
}

function makeLargeRequest(overrides: Partial<CreateRefundRequest> = {}): CreateRefundRequest {
  return makeRequest({ amountCents: 15_000_00, ...overrides }); // $15,000 – above threshold
}

function makeAuditLogger(): { logger: AuditLogger; events: Array<{ action: string; ctx: unknown }> } {
  const events: Array<{ action: string; ctx: unknown }> = [];
  const logger: AuditLogger = {
    log: async (action: any, ctx?: any, _opts?: any) => {
      const eventAction = typeof action === "string" ? action : action?.action ?? "";
      events.push({ action: eventAction, ctx });
    },
  };
  return { logger, events };
}

let tick = 0;
function makeClock(startMs = 1_000_000) {
  return () => startMs + tick * 1000;
}

// ─── Tests ────────────────────────────────────────────────────────────────────

describe("PartialRefundApprovalService – #478", () => {
  let service: PartialRefundApprovalService;
  let auditEvents: Array<{ action: string; ctx: unknown }>;
  let nowMs: number;

  beforeEach(() => {
    tick = 0;
    nowMs = 1_000_000;
    const { logger, events } = makeAuditLogger();
    auditEvents = events;
    service = new PartialRefundApprovalService({
      auditLogger: logger,
      now: () => nowMs,
    });
  });

  // ── Threshold checks ──────────────────────────────────────────────────────

  describe("requiresApproval()", () => {
    it("returns false when amount is below USD threshold", () => {
      expect(service.requiresApproval(makeRequest({ amountCents: 9_999_99, currency: "USD" }))).toBe(false);
    });

    it("returns true when amount equals USD threshold", () => {
      expect(service.requiresApproval(makeRequest({ amountCents: DEFAULT_THRESHOLDS.USD, currency: "USD" }))).toBe(true);
    });

    it("returns true when amount exceeds USD threshold", () => {
      expect(service.requiresApproval(makeLargeRequest())).toBe(true);
    });

    it("uses GBP threshold independently", () => {
      expect(service.requiresApproval(makeRequest({ amountCents: DEFAULT_THRESHOLDS.GBP, currency: "GBP" }))).toBe(true);
      expect(service.requiresApproval(makeRequest({ amountCents: DEFAULT_THRESHOLDS.GBP - 1, currency: "GBP" }))).toBe(false);
    });

    it("never requires approval for unknown currency (no threshold = Infinity)", () => {
      expect(service.requiresApproval(makeRequest({ amountCents: 999_999_999, currency: "UNKNOWN" }))).toBe(false);
    });
  });

  // ── initiate ──────────────────────────────────────────────────────────────

  describe("initiate()", () => {
    it("auto-approves small refunds without creating a pending request", async () => {
      const result = await service.initiate(makeRequest(), "admin-a");
      expect(result.requiresApproval).toBe(false);
      expect(result.autoApproved).toBeDefined();
      expect(result.pendingRequest).toBeUndefined();
    });

    it("creates a pending request for large refunds", async () => {
      const result = await service.initiate(makeLargeRequest(), "admin-a");
      expect(result.requiresApproval).toBe(true);
      expect(result.pendingRequest).toBeDefined();
      expect(result.pendingRequest!.status).toBe("pending");
      expect(result.pendingRequest!.initiatorId).toBe("admin-a");
    });

    it("sets expiry on pending request", async () => {
      const result = await service.initiate(makeLargeRequest(), "admin-a");
      const ttl = 30 * 60 * 1000;
      expect(result.pendingRequest!.expiresAt).toBe(nowMs + ttl);
    });

    it("emits audit event for pending request", async () => {
      await service.initiate(makeLargeRequest(), "admin-a");
      expect(auditEvents.some((e) => e.action.includes("initiated"))).toBe(true);
    });

    it("emits audit event for auto-approved request", async () => {
      await service.initiate(makeRequest(), "admin-a");
      expect(auditEvents.some((e) => e.action.includes("auto_approved"))).toBe(true);
    });

    it("rejects empty initiatorId", async () => {
      await expect(service.initiate(makeLargeRequest(), "")).rejects.toThrow(RefundApprovalError);
    });
  });

  // ── approve ───────────────────────────────────────────────────────────────

  describe("approve()", () => {
    it("approves a pending request by a different admin", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      const result = await service.approve(pendingRequest!.id, "admin-b");
      expect(result.approvedRequest.status).toBe("approved");
      expect(result.approvedRequest.approverId).toBe("admin-b");
      expect(result.refundRequest.amountCents).toBe(15_000_00);
    });

    it("throws SELF_APPROVAL when the initiator tries to approve", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      await expect(service.approve(pendingRequest!.id, "admin-a")).rejects.toMatchObject({
        code: "SELF_APPROVAL",
      });
    });

    it("throws NOT_FOUND for unknown approvalId", async () => {
      await expect(service.approve("nonexistent", "admin-b")).rejects.toMatchObject({
        code: "NOT_FOUND",
      });
    });

    it("throws ALREADY_RESOLVED for already-approved request", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      await service.approve(pendingRequest!.id, "admin-b");
      await expect(service.approve(pendingRequest!.id, "admin-c")).rejects.toMatchObject({
        code: "ALREADY_RESOLVED",
      });
    });

    it("emits audit event on approval", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      await service.approve(pendingRequest!.id, "admin-b");
      expect(auditEvents.some((e) => e.action.includes("approved"))).toBe(true);
    });

    it("throws EXPIRED when TTL has passed", async () => {
      const svc = new PartialRefundApprovalService({
        approvalTtlMs: 1000,
        now: () => nowMs,
      });
      const { pendingRequest } = await svc.initiate(makeLargeRequest(), "admin-a");

      // Advance clock past TTL
      nowMs += 2000;
      await expect(svc.approve(pendingRequest!.id, "admin-b")).rejects.toMatchObject({
        code: "EXPIRED",
      });
    });
  });

  // ── deny ─────────────────────────────────────────────────────────────────

  describe("deny()", () => {
    it("denies a pending request", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      const denied = await service.deny(pendingRequest!.id, "admin-b", "policy violation");
      expect(denied.status).toBe("denied");
      expect(denied.deniedById).toBe("admin-b");
      expect(denied.deniedReason).toBe("policy violation");
    });

    it("throws NOT_FOUND for unknown id", async () => {
      await expect(service.deny("ghost", "admin-b")).rejects.toMatchObject({ code: "NOT_FOUND" });
    });

    it("throws ALREADY_RESOLVED after approval", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      await service.approve(pendingRequest!.id, "admin-b");
      await expect(service.deny(pendingRequest!.id, "admin-c")).rejects.toMatchObject({
        code: "ALREADY_RESOLVED",
      });
    });

    it("emits audit event on denial", async () => {
      const { pendingRequest } = await service.initiate(makeLargeRequest(), "admin-a");
      await service.deny(pendingRequest!.id, "admin-b");
      expect(auditEvents.some((e) => e.action.includes("denied"))).toBe(true);
    });
  });

  // ── expiry ────────────────────────────────────────────────────────────────

  describe("expiry", () => {
    it("getById marks a pending request as expired after TTL", async () => {
      const svc = new PartialRefundApprovalService({
        approvalTtlMs: 5000,
        now: () => nowMs,
      });
      const { pendingRequest } = await svc.initiate(makeLargeRequest(), "admin-a");
      nowMs += 6000;

      const result = svc.getById(pendingRequest!.id);
      expect(result?.status).toBe("expired");
    });

    it("list() surfaces expired requests under 'expired' filter", async () => {
      const svc = new PartialRefundApprovalService({
        approvalTtlMs: 1000,
        now: () => nowMs,
      });
      await svc.initiate(makeLargeRequest(), "admin-a");
      nowMs += 2000;

      const expired = svc.list({ status: "expired" });
      expect(expired).toHaveLength(1);
    });
  });

  // ── list ──────────────────────────────────────────────────────────────────

  describe("list()", () => {
    it("returns all requests when no filter given", async () => {
      await service.initiate(makeLargeRequest({ paymentId: "pay-1" }), "admin-a");
      await service.initiate(makeLargeRequest({ paymentId: "pay-2" }), "admin-a");
      expect(service.list()).toHaveLength(2);
    });

    it("filters by status correctly", async () => {
      const { pendingRequest: r1 } = await service.initiate(makeLargeRequest({ paymentId: "pay-1" }), "admin-a");
      const { pendingRequest: r2 } = await service.initiate(makeLargeRequest({ paymentId: "pay-2" }), "admin-a");

      await service.approve(r1!.id, "admin-b");

      expect(service.list({ status: "pending" })).toHaveLength(1);
      expect(service.list({ status: "approved" })).toHaveLength(1);
    });
  });

  // ── custom thresholds ─────────────────────────────────────────────────────

  describe("custom thresholds", () => {
    it("respects lower per-currency threshold", async () => {
      const svc = new PartialRefundApprovalService({
        thresholds: { USD: 100_00 }, // $100
      });
      expect(svc.requiresApproval(makeRequest({ amountCents: 100_00 }))).toBe(true);
      expect(svc.requiresApproval(makeRequest({ amountCents: 99_99 }))).toBe(false);
    });
  });
});

import { StrikeService, strikeService } from "../strikeService.js";

describe("StrikeService Unit Tests", () => {
  let service: StrikeService;

  beforeEach(() => {
    service = new StrikeService();
    strikeService.resetState();
  });

  describe("Configuration", () => {
    it("should initialize with default configuration", () => {
      const config = service.getConfig();
      expect(config.maxStrikesThreshold).toBe(3);
      expect(config.decayWindowMs).toBe(30 * 24 * 60 * 60 * 1000);
      expect(config.autoSuspendEnabled).toBe(true);
    });

    it("should update configuration with valid values", () => {
      const updated = service.updateConfig({ maxStrikesThreshold: 5, decayWindowMs: 7 * 24 * 60 * 60 * 1000 });
      expect(updated.maxStrikesThreshold).toBe(5);
      expect(updated.decayWindowMs).toBe(7 * 24 * 60 * 60 * 1000);
    });

    it("should throw on invalid configuration updates", () => {
      expect(() => service.updateConfig({ maxStrikesThreshold: 0 })).toThrow("maxStrikesThreshold must be a positive integer");
      expect(() => service.updateConfig({ decayWindowMs: -100 })).toThrow("decayWindowMs must be a positive number");
    });
  });

  describe("Strike Issuance & Auto-Suspension", () => {
    it("should throw an error if buyerId is empty", async () => {
      await expect(service.issueStrike({ buyerId: "" })).rejects.toThrow("buyerId is required");
    });

    it("should issue a strike and increment active strike count", async () => {
      const buyerId = "buyer-1";
      const { strike, autoSuspended } = await service.issueStrike({
        buyerId,
        reason: "Missed appointment",
        intentId: "intent-101",
        slotId: "slot-202",
      });

      expect(strike.id).toBeDefined();
      expect(strike.buyerId).toBe(buyerId);
      expect(strike.status).toBe("active");
      expect(autoSuspended).toBe(false);

      const activeStrikes = service.getActiveStrikes(buyerId);
      expect(activeStrikes.length).toBe(1);
      expect(activeStrikes[0].id).toBe(strike.id);
    });

    it("should trigger auto-suspension when reaching max strikes threshold", async () => {
      const buyerId = "buyer-threshold-test";
      const t0 = 1000000;

      // Strike 1
      const res1 = await service.issueStrike({ buyerId, issuedAt: t0 });
      expect(res1.autoSuspended).toBe(false);

      // Strike 2
      const res2 = await service.issueStrike({ buyerId, issuedAt: t0 + 1000 });
      expect(res2.autoSuspended).toBe(false);

      // Strike 3 (threshold reached!)
      const res3 = await service.issueStrike({ buyerId, issuedAt: t0 + 2000 });
      expect(res3.autoSuspended).toBe(true);
      expect(res3.buyerSuspension.isSuspended).toBe(true);
      expect(res3.buyerSuspension.activeStrikesAtSuspension).toBe(3);

      // Strike 4 while already suspended
      const res4 = await service.issueStrike({ buyerId, issuedAt: t0 + 3000 });
      expect(res4.autoSuspended).toBe(false); // Already suspended
      expect(res4.buyerSuspension.isSuspended).toBe(true);
    });
  });

  describe("Decay Policy & Boundaries", () => {
    it("should decay strikes after decayWindowMs has elapsed (exact boundary tests)", async () => {
      const buyerId = "buyer-decay-test";
      const decayMs = 10000; // 10 seconds decay for test
      service.updateConfig({ decayWindowMs: decayMs });

      const t0 = 1000;

      const { strike } = await service.issueStrike({ buyerId, issuedAt: t0 });

      // Before decay boundary (t0 + 9999ms): Active
      expect(service.getActiveStrikes(buyerId, t0 + 9999).length).toBe(1);

      // At exact decay boundary (t0 + 10000ms): Expired / Decayed
      expect(service.getActiveStrikes(buyerId, t0 + 10000).length).toBe(0);

      // After decay boundary (t0 + 10001ms): Expired / Decayed
      expect(service.getActiveStrikes(buyerId, t0 + 10001).length).toBe(0);

      // Total strikes recorded maintains historical decay status
      const allStrikes = service.getBuyerStrikes(buyerId, t0 + 10000);
      expect(allStrikes[0].status).toBe("decayed");
    });

    it("should not trigger suspension if old strikes have decayed below threshold", async () => {
      const buyerId = "buyer-decay-suspension";
      const decayMs = 5000;
      service.updateConfig({ decayWindowMs: decayMs, maxStrikesThreshold: 3 });

      const t0 = 1000;
      await service.issueStrike({ buyerId, issuedAt: t0 });
      await service.issueStrike({ buyerId, issuedAt: t0 + 1000 });

      // Fast forward past decay window for strike 1 and 2
      const t1 = t0 + 6000; // strikes 1 & 2 have decayed

      // Issue new strike
      const res = await service.issueStrike({ buyerId, issuedAt: t1 });

      expect(res.autoSuspended).toBe(false);
      expect(service.getActiveStrikes(buyerId, t1).length).toBe(1);
    });
  });

  describe("Appeal Path & Suspension Reversal", () => {
    it("should fail to appeal non-existent or inactive strike", async () => {
      await expect(service.appealStrike("non-existent", "reason")).rejects.toThrow("not found");
      await expect(service.appealStrike("", "reason")).rejects.toThrow("strikeId is required");
      await expect(service.appealStrike("s1", "")).rejects.toThrow("appealReason is required");
    });

    it("should appeal a strike and reverse account suspension if active strikes fall below threshold", async () => {
      const buyerId = "buyer-appeal-test";
      service.updateConfig({ maxStrikesThreshold: 3 });

      const t0 = 1000;
      const s1 = await service.issueStrike({ buyerId, issuedAt: t0 });
      const s2 = await service.issueStrike({ buyerId, issuedAt: t0 + 100 });
      const s3 = await service.issueStrike({ buyerId, issuedAt: t0 + 200 });

      expect(s3.buyerSuspension.isSuspended).toBe(true);

      // Appeal strike 3
      const appealRes = await service.appealStrike(s3.strike.id, "Medical emergency justification", t0 + 500);

      expect(appealRes.strike.status).toBe("appealed");
      expect(appealRes.strike.appealReason).toBe("Medical emergency justification");
      expect(appealRes.suspensionLifted).toBe(true);
      expect(appealRes.buyerSuspension.isSuspended).toBe(false);

      // Active strikes count is now 2
      expect(service.getActiveStrikes(buyerId, t0 + 500).length).toBe(2);

      // Attempting to appeal already appealed strike throws error
      await expect(service.appealStrike(s3.strike.id, "Another appeal", t0 + 600)).rejects.toThrow("is not active");
    });
  });

  describe("Admin Reinstatement Workflow", () => {
    it("should allow admin to reinstate suspended buyer and clear active strikes", async () => {
      const buyerId = "buyer-reinstate-test";
      const t0 = 1000;

      await service.issueStrike({ buyerId, issuedAt: t0 });
      await service.issueStrike({ buyerId, issuedAt: t0 + 10 });
      await service.issueStrike({ buyerId, issuedAt: t0 + 20 });

      const statusBefore = service.getBuyerSuspensionStatus(buyerId, t0 + 30);
      expect(statusBefore.isSuspended).toBe(true);

      const reinstateRes = await service.reinstateBuyer(
        buyerId,
        { adminId: "admin-42", reason: "Good faith exception", clearActiveStrikes: true },
        t0 + 100
      );

      expect(reinstateRes.buyerSuspension.isSuspended).toBe(false);
      expect(reinstateRes.buyerSuspension.reinstatedBy).toBe("admin-42");
      expect(reinstateRes.rescindedStrikesCount).toBe(3);

      const activeAfter = service.getActiveStrikes(buyerId, t0 + 100);
      expect(activeAfter.length).toBe(0);
    });

    it("should throw error if buyerId is empty on reinstatement", async () => {
      await expect(service.reinstateBuyer("")).rejects.toThrow("buyerId is required");
    });
  });

  describe("Edge Case: Simultaneous Strikes (Concurrency)", () => {
    it("should handle simultaneous rapid strikes without race conditions", async () => {
      const buyerId = "buyer-simultaneous-strikes";
      service.updateConfig({ maxStrikesThreshold: 3 });

      // Trigger 5 simultaneous strikes asynchronously
      const promises = Array.from({ length: 5 }).map((_, i) =>
        service.issueStrike({ buyerId, reason: `Concurrent strike ${i}` })
      );

      const results = await Promise.all(promises);

      expect(results.length).toBe(5);
      const suspensionStatus = service.getBuyerSuspensionStatus(buyerId);

      expect(suspensionStatus.isSuspended).toBe(true);
      expect(suspensionStatus.activeStrikesCount).toBe(5);
    });
  });
});

/**
 * SOC2 Access Review Service
 *
 * Provides quarterly access review attestation reports by:
 *   - Snapshotting current access grant assignments at a point in time
 *   - Generating reports in CSV and JSON formats for audit evidence
 *   - Tracking reviewer sign-off with reviewer, date, and outcome
 *
 * Security properties:
 *   - Snapshots are immutable once created
 *   - Attestations are append-only (immutable after creation)
 *   - All operations are audited via AuditLogger
 *   - Timing-safe token verification for report downloads
 */

import crypto from "node:crypto";
import fs from "fs";
import fsPromises from "fs/promises";
import path from "path";
import { AuditLogger } from "./auditLogger.js";
import { buildRoleHierarchy } from "../middleware/rbac.js";
import type { RoleHierarchy } from "../middleware/rbac.js";
import type {
  AccessGrantEntry,
  AccessGrantSnapshot,
  AccessReviewAttestation,
  AccessReviewReport,
  AttestationOutcome,
  QuarterLabel,
  QuarterGapResult,
  ListSnapshotsOptions,
  ListSnapshotsResult,
  ListAttestationsOptions,
  ListAttestationsResult,
  ReportFormat,
  SnapshotSummary,
} from "../types/accessReview.js";

// ─── Constants ────────────────────────────────────────────────────────────────

const DEFAULT_LIST_LIMIT = 50;
const MAX_LIST_LIMIT = 200;
const ROLES_CONFIG_URL = new URL("../config/roles.json", import.meta.url);

// ─── Helpers ──────────────────────────────────────────────────────────────────

function generateId(): string {
  return crypto.randomUUID();
}

/**
 * Compute the current quarter label from a Date.
 * Returns e.g. "2026-Q2" for April-June 2026.
 */
export function computeQuarterLabel(date: Date = new Date()): QuarterLabel {
  const year = date.getFullYear();
  const month = date.getMonth(); // 0-indexed
  const quarter = Math.floor(month / 3) + 1;
  return `${year}-Q${quarter}`;
}

/**
 * Compute quarter boundaries (start and end) for a given quarter label.
 */
export function computeQuarterRange(quarterLabel: QuarterLabel): { start: Date; end: Date } {
  const [yearStr, qStr] = quarterLabel.split("-Q");
  const year = Number.parseInt(yearStr, 10);
  const quarter = Number.parseInt(qStr, 10);
  if (Number.isNaN(year) || Number.isNaN(quarter) || quarter < 1 || quarter > 4) {
    throw new Error(`Invalid quarter label: ${quarterLabel}`);
  }
  const startMonth = (quarter - 1) * 3;
  const start = new Date(year, startMonth, 1, 0, 0, 0, 0);
  const end = new Date(year, startMonth + 3, 0, 23, 59, 59, 999);
  return { start, end };
}

/**
 * Generate previous quarter labels going back `count` quarters.
 */
export function generatePreviousQuarters(count: number, from: Date = new Date()): QuarterLabel[] {
  const quarters: QuarterLabel[] = [];
  const current = computeQuarterLabel(from);
  const [yearStr, qStr] = current.split("-Q");
  let year = Number.parseInt(yearStr, 10);
  let quarter = Number.parseInt(qStr, 10);

  for (let i = 0; i < count; i++) {
    quarters.push(`${year}-Q${quarter}`);
    quarter--;
    if (quarter < 1) {
      quarter = 4;
      year--;
    }
  }
  return quarters;
}

/**
 * Build access grant entries from the role hierarchy.
 * Each known role gets an entry with its effective permissions and implied roles.
 */
export function buildGrantEntriesFromHierarchy(roleHierarchy: RoleHierarchy): AccessGrantEntry[] {
  const entries: AccessGrantEntry[] = [];

  for (const role of roleHierarchy.roles) {
    const effective = roleHierarchy.effectiveRolesByRole.get(role);
    if (!effective) continue;

    const impliedRoles = Array.from(effective).filter((r) => r !== role);
    entries.push({
      role,
      effectivePermissions: Array.from(effective).sort(),
      impliedRoles: impliedRoles.sort(),
      source: "roles.json",
    });
  }

  return entries.sort((a, b) => a.role.localeCompare(b.role));
}

/**
 * Default role hierarchy used when roles.json cannot be loaded.
 * Provides minimal safe defaults.
 */
export function getDefaultRoleHierarchy(): RoleHierarchy {
  return buildRoleHierarchy({
    roles: {
      admin: ["support", "professional", "customer"],
      support: ["auditor"],
      auditor: [],
      professional: [],
      customer: [],
    },
  });
}

/**
 * Read and parse the roles.json configuration file.
 */
export function readRolesConfigFromDisk(): { roles: Record<string, string[]> } {
  try {
    const raw = fs.readFileSync(ROLES_CONFIG_URL, "utf8");
    return JSON.parse(raw) as { roles: Record<string, string[]> };
  } catch {
    return {
      roles: {
        admin: ["support", "professional", "customer"],
        support: ["auditor"],
        auditor: [],
        professional: [],
        customer: [],
      },
    };
  }
}

// ─── In-memory store types ────────────────────────────────────────────────────

interface SnapshotStore {
  snapshots: Map<string, AccessGrantSnapshot>;
  attestations: Map<string, AccessReviewAttestation>;
}

// ─── AccessReviewService ──────────────────────────────────────────────────────

export class AccessReviewService {
  private readonly store: SnapshotStore = {
    snapshots: new Map(),
    attestations: new Map(),
  };
  private readonly logger: AuditLogger;

  constructor(logger?: AuditLogger) {
    this.logger = logger ?? new AuditLogger();
  }

  // ── Snapshot Management ───────────────────────────────────────────────────

  /**
   * Take a point-in-time snapshot of the access grant assignments.
   * Returns the created snapshot. If a snapshot already exists for the current
   * quarter, returns the existing one unless `force` is true.
   */
  public async createSnapshot(
    force: boolean = false,
    snapshotDate?: Date,
  ): Promise<AccessGrantSnapshot> {
    const date = snapshotDate ?? new Date();
    const quarterLabel = computeQuarterLabel(date);

    // Check for existing snapshot this quarter (unless forced)
    if (!force) {
      const existing = this.findSnapshotForQuarter(quarterLabel);
      if (existing) {
        await this.logger.log(
          "access-review.snapshot.skipped",
          {
            context: { quarterLabel, snapshotId: existing.snapshotId, reason: "already_exists" },
          },
          { status: 200 },
        );
        return existing;
      }
    }

    // Build the role hierarchy and grant entries
    const config = readRolesConfigFromDisk();
    const roleHierarchy = buildRoleHierarchy(config);
    const grants = buildGrantEntriesFromHierarchy(roleHierarchy);
    const snapshot: AccessGrantSnapshot = {
      snapshotId: generateId(),
      quarterLabel,
      snapshotDate: date.toISOString(),
      grants,
      createdAt: new Date().toISOString(),
    };

    this.store.snapshots.set(snapshot.snapshotId, snapshot);

    await this.logger.log(
      "access-review.snapshot.created",
      {
        context: {
          snapshotId: snapshot.snapshotId,
          quarterLabel,
          grantCount: grants.length,
        },
      },
      { status: 201 },
    );

    return snapshot;
  }

  /**
   * Retrieve a snapshot by its ID.
   */
  public getSnapshot(snapshotId: string): AccessGrantSnapshot | null {
    return this.store.snapshots.get(snapshotId) ?? null;
  }

  /**
   * List snapshots with optional filtering and pagination.
   */
  public listSnapshots(options?: ListSnapshotsOptions): ListSnapshotsResult {
    const limit = Math.min(options?.limit ?? DEFAULT_LIST_LIMIT, MAX_LIST_LIMIT);
    const offset = options?.offset ?? 0;

    let snapshots = Array.from(this.store.snapshots.values());

    // Apply quarter label filter
    if (options?.quarterLabel) {
      snapshots = snapshots.filter((s) => s.quarterLabel === options.quarterLabel);
    }

    // Sort by createdAt descending (most recent first)
    snapshots.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    const total = snapshots.length;
    const page = snapshots.slice(offset, offset + limit);

    return {
      snapshots: page,
      total,
      limit,
      offset,
    };
  }

  /**
   * Get lightweight snapshot summaries.
   */
  public listSnapshotSummaries(options?: ListSnapshotsOptions): {
    summaries: SnapshotSummary[];
    total: number;
    limit: number;
    offset: number;
  } {
    const result = this.listSnapshots(options);
    return {
      summaries: result.snapshots.map((s) => ({
        snapshotId: s.snapshotId,
        quarterLabel: s.quarterLabel,
        snapshotDate: s.snapshotDate,
        grantCount: s.grants.length,
        createdAt: s.createdAt,
      })),
      total: result.total,
      limit: result.limit,
      offset: result.offset,
    };
  }

  /**
   * Find snapshot for a given quarter, if one exists.
   */
  public findSnapshotForQuarter(quarterLabel: QuarterLabel): AccessGrantSnapshot | null {
    for (const snapshot of this.store.snapshots.values()) {
      if (snapshot.quarterLabel === quarterLabel) {
        return snapshot;
      }
    }
    return null;
  }

  /**
   * Detect gaps in quarterly snapshots.
   * Checks if there are missing quarters going back `lookback` quarters.
   */
  public detectGaps(lookback: number = 8): QuarterGapResult {
    const expectedQuarters = generatePreviousQuarters(lookback);
    const existingQuarters = new Set(
      Array.from(this.store.snapshots.values()).map((s) => s.quarterLabel),
    );

    const missingQuarters = expectedQuarters.filter((q) => !existingQuarters.has(q));
    const existingLabels = Array.from(this.store.snapshots.values())
      .map((s) => s.quarterLabel)
      .sort();
    const lastSnapshotQuarter = existingLabels.length > 0 ? existingLabels[existingLabels.length - 1] : null;

    return {
      hasGap: missingQuarters.length > 0,
      missingQuarters,
      lastSnapshotQuarter,
    };
  }

  // ── Attestation Management ────────────────────────────────────────────────

  /**
   * Record a reviewer sign-off (attestation) for a snapshot.
   * Returns the created attestation. Throws if the snapshot doesn't exist
   * or if a duplicate attestation (same reviewer + snapshot) exists.
   */
  public async createAttestation(
    snapshotId: string,
    reviewer: string,
    outcome: AttestationOutcome,
    notes?: string,
  ): Promise<AccessReviewAttestation> {
    const snapshot = this.getSnapshot(snapshotId);
    if (!snapshot) {
      throw new Error(`Snapshot not found: ${snapshotId}`);
    }

    if (!reviewer || typeof reviewer !== "string" || reviewer.trim().length === 0) {
      throw new Error("Reviewer identifier is required");
    }

    if (!["approved", "rejected", "needs_revision"].includes(outcome)) {
      throw new Error(
        `Invalid attestation outcome: ${outcome}. Must be approved, rejected, or needs_revision`,
      );
    }

    // Check for duplicate attestation
    const existingAttestations = Array.from(this.store.attestations.values()).filter(
      (a) => a.snapshotId === snapshotId && a.reviewer === reviewer,
    );
    if (existingAttestations.length > 0) {
      throw new Error(
        `Attestation already exists for snapshot ${snapshotId} by reviewer ${reviewer}. ` +
          `Existing outcome: ${existingAttestations[0].outcome}. Use updateAttestation to amend.`,
      );
    }

    const attestation: AccessReviewAttestation = {
      attestationId: generateId(),
      snapshotId,
      quarterLabel: snapshot.quarterLabel,
      reviewer: reviewer.trim(),
      reviewedAt: new Date().toISOString(),
      outcome,
      notes: notes?.trim(),
    };

    this.store.attestations.set(attestation.attestationId, attestation);

    await this.logger.log(
      "access-review.attestation.created",
      {
        context: {
          attestationId: attestation.attestationId,
          snapshotId,
          quarterLabel: snapshot.quarterLabel,
          reviewer: attestation.reviewer,
          outcome,
        },
      },
      { status: 201 },
    );

    return attestation;
  }

  /**
   * Retrieve an attestation by its ID.
   */
  public getAttestation(attestationId: string): AccessReviewAttestation | null {
    return this.store.attestations.get(attestationId) ?? null;
  }

  /**
   * List attestations with optional filtering and pagination.
   */
  public listAttestations(options?: ListAttestationsOptions): ListAttestationsResult {
    const limit = Math.min(options?.limit ?? DEFAULT_LIST_LIMIT, MAX_LIST_LIMIT);
    const offset = options?.offset ?? 0;

    let attestations = Array.from(this.store.attestations.values());

    if (options?.snapshotId) {
      attestations = attestations.filter((a) => a.snapshotId === options.snapshotId);
    }
    if (options?.quarterLabel) {
      attestations = attestations.filter((a) => a.quarterLabel === options.quarterLabel);
    }
    if (options?.outcome) {
      attestations = attestations.filter((a) => a.outcome === options.outcome);
    }

    // Sort by reviewedAt descending
    attestations.sort(
      (a, b) => new Date(b.reviewedAt).getTime() - new Date(a.reviewedAt).getTime(),
    );

    const total = attestations.length;
    const page = attestations.slice(offset, offset + limit);

    return {
      attestations: page,
      total,
      limit,
      offset,
    };
  }

  // ── Report Generation ────────────────────────────────────────────────────

  /**
   * Generate a complete access review report for a given snapshot ID.
   * The report includes both the snapshot data and any attestations.
   */
  public generateReport(snapshotId: string): AccessReviewReport {
    const snapshot = this.getSnapshot(snapshotId);
    if (!snapshot) {
      throw new Error(`Snapshot not found: ${snapshotId}`);
    }

    const attestations = this.listAttestations({ snapshotId });

    return {
      reportId: generateId(),
      quarterLabel: snapshot.quarterLabel,
      snapshot,
      attestations: attestations.attestations,
      generatedAt: new Date().toISOString(),
      reviewed: attestations.attestations.length > 0,
    };
  }

  /**
   * Generate a report in the requested format (JSON or CSV) as a string.
   */
  public generateFormattedReport(snapshotId: string, format: ReportFormat): string {
    const report = this.generateReport(snapshotId);

    if (format === "json") {
      return this.formatJsonReport(report);
    }

    return this.formatCsvReport(report);
  }

  /**
   * Format the report as a human-readable JSON string.
   */
  private formatJsonReport(report: AccessReviewReport): string {
    return JSON.stringify(report, null, 2);
  }

  /**
   * Format the report as CSV with separate sections for grants and attestations.
   */
  private formatCsvReport(report: AccessReviewReport): string {
    const lines: string[] = [];

    // Header section
    lines.push(`# SOC2 Access Review Report - ${report.quarterLabel}`);
    lines.push(`# Report ID: ${report.reportId}`);
    lines.push(`# Generated: ${report.generatedAt}`);
    lines.push(`# Snapshot: ${report.snapshot.snapshotId}`);
    lines.push(`# Snapshot Date: ${report.snapshot.snapshotDate}`);
    lines.push(`# Reviewed: ${report.reviewed}`);
    lines.push("");

    // Grant entries section
    lines.push("# Access Grants");
    lines.push("role,effective_permissions,implied_roles,source");
    for (const grant of report.snapshot.grants) {
      const permissions = grant.effectivePermissions.join("; ");
      const implied = grant.impliedRoles.join("; ");
      // Escape CSV fields that might contain commas or quotes
      const escapedPermissions = this.escapeCsvField(permissions);
      const escapedImplied = this.escapeCsvField(implied);
      lines.push(`${grant.role},${escapedPermissions},${escapedImplied},${grant.source}`);
    }
    lines.push("");

    // Attestation section
    lines.push("# Attestations");
    lines.push("attestation_id,reviewer,reviewed_at,outcome,notes");
    if (report.attestations.length === 0) {
      lines.push("N/A,N/A,N/A,pending_review,");
    } else {
      for (const att of report.attestations) {
        const escapedNotes = att.notes ? this.escapeCsvField(att.notes) : "";
        lines.push(
          `${att.attestationId},${att.reviewer},${att.reviewedAt},${att.outcome},${escapedNotes}`,
        );
      }
    }

    return lines.join("\n");
  }

  /**
   * Escape a CSV field value, wrapping in quotes if needed.
   */
  private escapeCsvField(value: string): string {
    if (value.includes(",") || value.includes('"') || value.includes("\n")) {
      return `"${value.replace(/"/g, '""')}"`;
    }
    return value;
  }

  /**
   * Export all attested snapshots as a combined JSON report bundle.
   */
  public generateAttestedReportsBundle(): string {
    const allAttestations = Array.from(this.store.attestations.values());
    const attestedSnapshotIds = new Set(allAttestations.map((a) => a.snapshotId));
    const reports: AccessReviewReport[] = [];

    for (const snapshotId of attestedSnapshotIds) {
      try {
        reports.push(this.generateReport(snapshotId));
      } catch {
        // Skip snapshots that no longer exist (should not happen)
      }
    }

    // Sort by quarter descending
    reports.sort((a, b) => b.quarterLabel.localeCompare(a.quarterLabel));

    return JSON.stringify(
      { reports, generatedAt: new Date().toISOString(), count: reports.length },
      null,
      2,
    );
  }

  /**
   * Export all attested reports as a combined CSV bundle.
   */
  public generateAttestedReportsCsvBundle(): string {
    const allAttestations = Array.from(this.store.attestations.values());
    const attestedSnapshotIds = new Set(allAttestations.map((a) => a.snapshotId));

    const sections: string[] = [];

    for (const snapshotId of attestedSnapshotIds) {
      const snapshot = this.getSnapshot(snapshotId);
      if (!snapshot) continue;

      const report = this.generateReport(snapshotId);
      sections.push(this.formatCsvReport(report));
      sections.push("");
    }

    return sections.join("\n");
  }

  // ── Persistence (for production use) ──────────────────────────────────────

  /**
   * Persist all snapshots and attestations to JSON files on disk.
   */
  public async persistToDisk(
    snapshotsPath?: string,
    attestationsPath?: string,
  ): Promise<void> {
    const cwd = typeof process !== "undefined" ? process.cwd() : ".";
    const snapshotsFile =
      snapshotsPath ?? path.join(cwd, "data", "access-review-snapshots.json");
    const attestationsFile =
      attestationsPath ?? path.join(cwd, "data", "access-review-attestations.json");

    const snapshotsDir = path.dirname(snapshotsFile);
    const attestationsDir = path.dirname(attestationsFile);

    await fsPromises.mkdir(snapshotsDir, { recursive: true });
    await fsPromises.mkdir(attestationsDir, { recursive: true });

    const snapshotsData = Array.from(this.store.snapshots.values());
    const attestationsData = Array.from(this.store.attestations.values());

    await fsPromises.writeFile(snapshotsFile, JSON.stringify(snapshotsData, null, 2), "utf8");
    await fsPromises.writeFile(attestationsFile, JSON.stringify(attestationsData, null, 2), "utf8");

    await this.logger.log(
      "access-review.persisted",
      {
        context: {
          snapshotsFile,
          attestationsFile,
          snapshotCount: snapshotsData.length,
          attestationCount: attestationsData.length,
        },
      },
      { status: 200 },
    );
  }

  /**
   * Load snapshots and attestations from disk, merging with in-memory state.
   */
  public async loadFromDisk(
    snapshotsPath?: string,
    attestationsPath?: string,
  ): Promise<void> {
    const cwd = typeof process !== "undefined" ? process.cwd() : ".";
    const snapshotsFile =
      snapshotsPath ?? path.join(cwd, "data", "access-review-snapshots.json");
    const attestationsFile =
      attestationsPath ?? path.join(cwd, "data", "access-review-attestations.json");

    try {
      const snapshotsRaw = await fsPromises.readFile(snapshotsFile, "utf8");
      const snapshots = JSON.parse(snapshotsRaw) as AccessGrantSnapshot[];
      for (const snapshot of snapshots) {
        this.store.snapshots.set(snapshot.snapshotId, snapshot);
      }
    } catch (err: any) {
      if (err?.code !== "ENOENT") throw err;
    }

    try {
      const attestationsRaw = await fsPromises.readFile(attestationsFile, "utf8");
      const attestations = JSON.parse(attestationsRaw) as AccessReviewAttestation[];
      for (const attestation of attestations) {
        this.store.attestations.set(attestation.attestationId, attestation);
      }
    } catch (err: any) {
      if (err?.code !== "ENOENT") throw err;
    }

    await this.logger.log(
      "access-review.loaded",
      {
        context: {
          snapshotsFile,
          attestationsFile,
          snapshotCount: this.store.snapshots.size,
          attestationCount: this.store.attestations.size,
        },
      },
      { status: 200 },
    );
  }

  // ── Test Helpers ─────────────────────────────────────────────────────────

  /**
   * Clear all in-memory data (for testing).
   */
  public clear(): void {
    this.store.snapshots.clear();
    this.store.attestations.clear();
  }

  /**
   * Inject a snapshot directly (for testing).
   */
  public injectSnapshot(snapshot: AccessGrantSnapshot): void {
    this.store.snapshots.set(snapshot.snapshotId, snapshot);
  }

  /**
   * Inject an attestation directly (for testing).
   */
  public injectAttestation(attestation: AccessReviewAttestation): void {
    this.store.attestations.set(attestation.attestationId, attestation);
  }
}

// ─── Default Singleton ────────────────────────────────────────────────────────

export const accessReviewService = new AccessReviewService();

/**
 * Test helper to rebuild the singleton with a fresh in-memory state.
 */
export function resetAccessReviewService(): void {
  accessReviewService.clear();
}

/**
 * GdprErasureOrchestrator.ts
 *
 * High-level orchestrator for GDPR Article 17 ("right to erasure") requests.
 *
 * ## Responsibilities
 *
 * 1. **Legal-hold guard** — refuses erasure for subjects under a legal hold.
 * 2. **Dependency graph walk** — processes tables in topological order (leaf
 *    tables first, root `users` row last) to respect FK constraints.
 * 3. **Null-with-hash tombstoning** — nulls PII columns, preserving SHA-256
 *    hashes where configured.
 * 4. **Transactional rollback** — runs all mutations inside a single DB
 *    transaction; any failure triggers a full rollback for this subject.
 * 5. **Erasure receipt** — writes a structured receipt to `gdpr_erasure_events`
 *    after a successful (or dry-run) erasure.
 * 6. **Audit logging** — emits `gdpr.erasure.requested`, `gdpr.erasure.completed`,
 *    and `gdpr.erasure.failed` events via `AuditLogger`.
 * 7. **Dry-run mode** — collects a full plan of actions without committing any
 *    database mutations; the receipt is still written (with `dryRun: true`).
 *
 * ## Usage
 *
 * ```ts
 * const orchestrator = new GdprErasureOrchestrator();
 * const receipt = await orchestrator.erase({
 *   subjectId: 'user-uuid',
 *   requestedBy: 'admin-uuid',
 *   dryRun: false,
 * });
 * ```
 *
 * ## Dependency injection
 *
 * All external dependencies (DB pool, legal-hold check, audit logger, event
 * log, graph) are injected so the orchestrator is fully unit-testable without
 * a real database.
 */

import crypto from "node:crypto";
import pool from "../../db/pool.js";
import type { PoolClient } from "pg";
import { LegalHoldService } from "../legalHoldService.js";
import { AuditLogger, defaultAuditLogger } from "../auditLogger.js";
import type { TableNode } from "./dependencyGraph.js";
import { getSortedGraph } from "./dependencyGraph.js";
import { tombstoneTable, type TableTombstoneResult } from "./tombstone.js";
import {
  type ErasureEventLog,
  type ErasureReceipt,
  PgErasureEventLog,
} from "./eventLog.js";

// ─── Types ────────────────────────────────────────────────────────────────────

/** Input parameters for an erasure request. */
export interface ErasureRequest {
  /** UUID of the data subject to erase. */
  subjectId: string;
  /** ID of the actor (admin) initiating the request. */
  requestedBy: string;
  /**
   * When true the orchestrator plans but does not execute any SQL mutations.
   * A receipt (with `dryRun: true`) is still written for the audit trail.
   */
  dryRun: boolean;
}

/** Detailed result including the receipt and per-table action plan. */
export interface ErasureResult {
  receipt: ErasureReceipt;
  /** Ordered list of per-table tombstone results (useful for dry-run previews). */
  tableResults: TableTombstoneResult[];
}

// ─── LegalHold port ───────────────────────────────────────────────────────────

/**
 * Minimal interface for checking legal holds, allowing injection of a test
 * double without depending on the concrete `LegalHoldService`.
 */
export interface LegalHoldChecker {
  isHeld(subjectId: string): Promise<boolean>;
}

// ─── Pool port ────────────────────────────────────────────────────────────────

/**
 * Minimal pool interface required by the orchestrator.
 */
export interface DbPool {
  connect(): Promise<PoolClient>;
}

// ─── Errors ───────────────────────────────────────────────────────────────────

/**
 * Thrown when an erasure is attempted for a subject under a legal hold.
 */
export class LegalHoldViolationError extends Error {
  constructor(public readonly subjectId: string) {
    super(`Erasure blocked: subject ${subjectId} is under a legal hold.`);
    this.name = "LegalHoldViolationError";
  }
}

// ─── Orchestrator ─────────────────────────────────────────────────────────────

export class GdprErasureOrchestrator {
  private readonly pool: DbPool;
  private readonly legalHold: LegalHoldChecker;
  private readonly auditLogger: AuditLogger;
  private readonly getGraph: () => TableNode[];

  constructor(opts?: {
    pool?: DbPool;
    legalHold?: LegalHoldChecker;
    auditLogger?: AuditLogger;
    getGraph?: () => TableNode[];
    /** Override the event log (e.g. for testing). */
    eventLog?: ErasureEventLog;
  }) {
    this.pool = opts?.pool ?? (pool as unknown as DbPool);
    this.legalHold = opts?.legalHold ?? LegalHoldService;
    this.auditLogger = opts?.auditLogger ?? defaultAuditLogger;
    this.getGraph = opts?.getGraph ?? getSortedGraph;
    this._eventLogOverride = opts?.eventLog;
  }

  /** Optional event log override (dependency injection for tests). */
  private readonly _eventLogOverride?: ErasureEventLog;

  /**
   * Execute a GDPR erasure for the given subject.
   *
   * @throws {LegalHoldViolationError}  if the subject has an active legal hold.
   * @throws any DB errors if the transaction cannot be committed (rolled back).
   */
  public async erase(request: ErasureRequest): Promise<ErasureResult> {
    const { subjectId, requestedBy, dryRun } = request;

    await this.auditLogger.log(
      "gdpr.erasure.requested",
      {
        context: { subjectId, requestedBy, dryRun },
      },
      { status: 202 },
    );

    // ── Legal-hold guard ──────────────────────────────────────────────────────
    const held = await this.legalHold.isHeld(subjectId);
    if (held) {
      await this.auditLogger.log(
        "gdpr.erasure.blocked.legalhold",
        { context: { subjectId, requestedBy } },
        { status: 409 },
      );
      throw new LegalHoldViolationError(subjectId);
    }

    // ── Obtain transaction client ─────────────────────────────────────────────
    const client = await this.pool.connect();
    const tableResults: TableTombstoneResult[] = [];

    try {
      if (!dryRun) {
        await client.query("BEGIN");
      }

      // ── Walk the FK graph ───────────────────────────────────────────────────
      const graph = this.getGraph();
      for (const node of graph) {
        const result = await tombstoneTable(
          client,
          node.table,
          node.pkCol,
          node.fkCol,
          node.piiColumns,
          subjectId,
          { dryRun },
        );
        tableResults.push(result);
      }

      // ── Build and write the receipt ─────────────────────────────────────────
      const receiptId = crypto.randomUUID();
      const erasedAt = new Date().toISOString();
      const tablesAffected = tableResults
        .filter((r) => r.actions.length > 0 || r.rowsAffected > 0)
        .map((r) => ({
          table: r.table,
          rowsAffected: dryRun ? r.actions.length : r.rowsAffected,
        }));

      const receipt: ErasureReceipt = {
        receiptId,
        subjectId,
        erasedAt,
        tablesAffected,
        totalRowsAffected: tablesAffected.reduce((sum, t) => sum + t.rowsAffected, 0),
        dryRun,
        requestedBy,
      };

      // Write receipt — within transaction for live runs, outside for dry-runs.
      const eventLog: ErasureEventLog =
        this._eventLogOverride ??
        (dryRun ? new PgErasureEventLog() : new PgErasureEventLog(client));

      await eventLog.writeReceipt(receipt);

      // ── Commit ───────────────────────────────────────────────────────────────
      if (!dryRun) {
        await client.query("COMMIT");
      }

      await this.auditLogger.log(
        "gdpr.erasure.completed",
        {
          context: {
            receiptId,
            subjectId,
            requestedBy,
            dryRun,
            tablesAffected: tablesAffected.length,
            totalRowsAffected: receipt.totalRowsAffected,
          },
        },
        { status: 200 },
      );

      return { receipt, tableResults };
    } catch (error) {
      if (!dryRun) {
        try {
          await client.query("ROLLBACK");
        } catch {
          // Swallow rollback errors; the original error takes precedence.
        }
      }

      await this.auditLogger.log(
        "gdpr.erasure.failed",
        {
          context: {
            subjectId,
            requestedBy,
            dryRun,
            error: error instanceof Error ? error.message : String(error),
          },
        },
        { status: 500 },
      );

      throw error;
    } finally {
      client.release();
    }
  }
}

/** Default singleton for application-wide use. */
export const defaultGdprErasureOrchestrator = new GdprErasureOrchestrator();

/**
 * Hold Fee Retention Policy
 *
 * Some suppliers charge a small non-refundable hold fee for refundable holds.
 * This module provides a per-supplier policy model that defaults to zero
 * retention (no hold fee).
 *
 * The hold fee is captured as a snapshot at booking creation time and deducted
 * from any refund that is subsequently issued. The disclosed retention amount
 * is visible in the refund breakdown (see RefundBreakdown.holdFee).
 */

import type { AuditLogger } from "./auditLogger.js";
import { defaultAuditLogger } from "./auditLogger.js";

// ─── Types ─────────────────────────────────────────────────────────────────────

/**
 * Per-supplier hold fee configuration.
 * The `holdFeeCents` is the non-refundable amount in the smallest currency unit
 * (e.g. cents for fiat, stroops for XLM). Defaults to 0 when not configured.
 */
export interface HoldFeePolicy {
  /** Supplier this policy applies to. */
  supplierId: string;
  /**
   * Non-refundable hold fee in smallest currency unit.
   * Must be >= 0 (0 means no hold fee / fully refundable hold).
   */
  holdFeeCents: number;
  /** ISO 8601 timestamp when this policy was created/updated. */
  updatedAt: string;
}

/**
 * Immutable snapshot of the hold fee policy captured at booking creation time.
 * Stored on the BookingIntentRecord for auditability — the hold fee that
 * applies to a booking never changes after creation, even if the supplier
 * later updates their policy.
 */
export interface HoldFeePolicySnapshot {
  /** Supplier who owns the policy. */
  supplierId: string;
  /** Non-refundable hold fee in cents, captured at booking time. */
  holdFeeCents: number;
  /** Timestamp (ms) when the snapshot was captured. */
  capturedAtMs: number;
}

// ─── Registry ──────────────────────────────────────────────────────────────────

export interface HoldFeePolicyRegistry {
  entries: Record<string, HoldFeePolicy>;
}

/**
 * Create an empty registry with no suppliers configured.
 * All suppliers default to 0 hold fee.
 */
export function createEmptyHoldFeeRegistry(): HoldFeePolicyRegistry {
  return { entries: {} };
}

/**
 * Resolve the effective hold fee for a supplier.
 * If the supplier has configured a policy, uses that; otherwise defaults to 0.
 */
export function resolveHoldFeeCents(
  registry: HoldFeePolicyRegistry,
  supplierId: string,
): number {
  const policy = registry.entries[supplierId];
  if (!policy) return 0;
  return Math.max(0, policy.holdFeeCents);
}

// ─── Validation ────────────────────────────────────────────────────────────────

export function validateHoldFeePolicy(policy: HoldFeePolicy): void {
  if (!policy.supplierId || typeof policy.supplierId !== "string") {
    throw new Error("HoldFeePolicy: supplierId must be a non-empty string");
  }
  if (!Number.isFinite(policy.holdFeeCents) || policy.holdFeeCents < 0) {
    throw new Error(
      `HoldFeePolicy: holdFeeCents must be a finite non-negative number, got ${policy.holdFeeCents}`,
    );
  }
  if (policy.holdFeeCents > 1_000_000_000) {
    throw new Error("HoldFeePolicy: holdFeeCents exceeds maximum allowed (1_000_000_000)");
  }
}

// ─── Service ───────────────────────────────────────────────────────────────────

export interface HoldFeePolicyServiceDeps {
  getRegistry?: () => HoldFeePolicyRegistry;
  auditLogger?: AuditLogger;
  nowMs?: () => number;
}

export class HoldFeePolicyService {
  private readonly getRegistry: () => HoldFeePolicyRegistry;
  private readonly auditLogger: AuditLogger;
  private readonly nowMs: () => number;

  constructor(deps: HoldFeePolicyServiceDeps = {}) {
    const defaultRegistry = createEmptyHoldFeeRegistry();
    this.getRegistry = deps.getRegistry ?? (() => defaultRegistry);
    this.auditLogger = deps.auditLogger ?? defaultAuditLogger;
    this.nowMs = deps.nowMs ?? (() => Date.now());
  }

  /**
   * Capture a snapshot of the hold fee policy for a supplier at the current
   * moment. This snapshot is intended to be stored on a BookingIntentRecord
   * so that the hold fee applicable at booking creation time is grandfathered.
   */
  snapshotForSupplier(supplierId: string): HoldFeePolicySnapshot {
    const registry = this.getRegistry();
    const holdFeeCents = resolveHoldFeeCents(registry, supplierId);
    return {
      supplierId,
      holdFeeCents,
      capturedAtMs: this.nowMs(),
    };
  }

  /**
   * Compute the retention (non-refundable hold fee) given a snapshot.
   * Returns 0 for empty/missing snapshots.
   */
  computeRetention(snapshot?: HoldFeePolicySnapshot): number {
    if (!snapshot) return 0;
    return Math.max(0, snapshot.holdFeeCents);
  }

  /**
   * Deduct the hold fee retention from a refund amount.
   * Returns the net refund after retention (clamped to 0).
   */
  deductRetention(refundAmount: number, snapshot?: HoldFeePolicySnapshot): number {
    const retention = this.computeRetention(snapshot);
    return Math.max(0, refundAmount - retention);
  }

  /**
   * Register or update a hold fee policy for a supplier.
   * If the supplier already has a policy, it is overwritten.
   */
  upsertPolicy(
    registry: HoldFeePolicyRegistry,
    params: {
      supplierId: string;
      holdFeeCents: number;
    },
  ): HoldFeePolicyRegistry {
    const { supplierId, holdFeeCents } = params;
    const nowIso = new Date(this.nowMs()).toISOString();

    const policy: HoldFeePolicy = {
      supplierId,
      holdFeeCents: Math.max(0, holdFeeCents),
      updatedAt: nowIso,
    };

    validateHoldFeePolicy(policy);

    const newEntries = { ...registry.entries, [supplierId]: policy };

    this.auditLogger
      .log("hold_fee_policy.upserted", {
        context: { supplierId, holdFeeCents, updatedAt: nowIso },
      }, { status: 200, resource: `hold-fee-policy:${supplierId}` })
      .catch(() => {});

    return { entries: newEntries };
  }

  /**
   * Get the policy for a supplier, or undefined if none configured.
   */
  getPolicy(registry: HoldFeePolicyRegistry, supplierId: string): HoldFeePolicy | undefined {
    return registry.entries[supplierId];
  }

  /**
   * List all configured policies.
   */
  listPolicies(registry: HoldFeePolicyRegistry): HoldFeePolicy[] {
    return Object.values(registry.entries).sort((a, b) =>
      a.supplierId.localeCompare(b.supplierId),
    );
  }
}

/**
 * AwsKmsAdapter tests
 *
 * - Exercises the full IHsmAdapter contract via the shared suite
 * - Adds AWS-specific unit tests for error classification, retry logic,
 *   and RotateKeyOnDemandCommand behaviour
 */

import { describe, it, expect, jest } from "@jest/globals";
import {
  KMSClient,
  NotFoundException,
  AccessDeniedException,
  DisabledException,
  InvalidKeyUsageException,
  KMSInvalidSignatureException,
  KMSServiceException,
  SigningAlgorithmSpec,
} from "@aws-sdk/client-kms";
import { AwsKmsAdapter } from "../aws-kms-adapter.js";
import { HsmError } from "../types.js";
import type { SigningAlgorithm } from "../types.js";
import { runHsmAdapterContractTests } from "./hsm-adapter.contract.js";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const KEY_ID = "arn:aws:kms:us-east-1:123456789012:key/test-key-id";
const TEST_MSG = new Uint8Array([1, 2, 3]);
const TEST_SIG = new Uint8Array([10, 20, 30]);
const ALGORITHM: SigningAlgorithm = "ECDSA_SHA_256";

/** Build a mock KMSClient whose `send` resolves/rejects as specified. */
function makeMockClient(
  sendImpl: (command: unknown) => Promise<unknown>,
): KMSClient {
  const client = new KMSClient({ region: "us-east-1" });
  jest.spyOn(client, "send").mockImplementation(sendImpl as Parameters<typeof jest.spyOn>[1]);
  return client;
}

function makeKmsException(
  name: string,
  statusCode: number,
  message = "KMS error",
): KMSServiceException {
  const err = new KMSServiceException({ name, $fault: "client", $metadata: { httpStatusCode: statusCode }, message });
  Object.defineProperty(err, "name", { value: name });
  return err;
}

// ---------------------------------------------------------------------------
// Contract suite wiring
// ---------------------------------------------------------------------------

runHsmAdapterContractTests("AwsKmsAdapter", {
  makeHappyAdapter(opts = {}) {
    const sig = opts.signature ?? TEST_SIG;
    const kv = opts.keyVersion ?? KEY_ID;
    const newKv = opts.newKeyVersion ?? KEY_ID;

    const client = makeMockClient(async (cmd: unknown) => {
      const cmdName = (cmd as { constructor: { name: string } }).constructor.name;
      if (cmdName === "SignCommand") {
        return { Signature: sig, KeyId: kv, SigningAlgorithm: SigningAlgorithmSpec.ECDSA_SHA_256 };
      }
      if (cmdName === "VerifyCommand") {
        return { SignatureValid: true, KeyId: kv };
      }
      if (cmdName === "DescribeKeyCommand") {
        return { KeyMetadata: { KeyId: kv } };
      }
      if (cmdName === "RotateKeyOnDemandCommand") {
        return { KeyId: newKv };
      }
      return {};
    });

    return new AwsKmsAdapter({ clientFactory: () => client });
  },

  makeErrorAdapter(code: string) {
    const client = makeMockClient(async () => {
      const hsmErr = new HsmError(`Simulated ${code}`, code as HsmError["code"]);
      throw hsmErr;
    });
    return new AwsKmsAdapter({ clientFactory: () => client });
  },

  makeFailoverAdapter() {
    let callCount = 0;
    // First client (first region) throws PROVIDER_ERROR; second succeeds
    const failClient = makeMockClient(async () => {
      throw new HsmError("region down", "PROVIDER_ERROR");
    });
    const successClient = makeMockClient(async (cmd: unknown) => {
      const cmdName = (cmd as { constructor: { name: string } }).constructor.name;
      if (cmdName === "SignCommand") {
        return { Signature: TEST_SIG, KeyId: KEY_ID, SigningAlgorithm: SigningAlgorithmSpec.ECDSA_SHA_256 };
      }
      return { Signature: TEST_SIG, KeyId: KEY_ID };
    });

    return new AwsKmsAdapter({
      regions: ["us-east-1", "us-west-2"],
      clientFactory: (region) => {
        callCount++;
        return region === "us-east-1" ? failClient : successClient;
      },
    });
  },

  makeAllRegionsFailAdapter() {
    const client = makeMockClient(async () => {
      throw new HsmError("all down", "PROVIDER_ERROR");
    });
    return new AwsKmsAdapter({
      regions: ["us-east-1", "us-west-2"],
      clientFactory: () => client,
    });
  },

  makeVerifyValidAdapter() {
    const client = makeMockClient(async () => ({
      SignatureValid: true,
      KeyId: KEY_ID,
    }));
    return new AwsKmsAdapter({ clientFactory: () => client });
  },

  makeVerifyInvalidAdapter() {
    const client = makeMockClient(async () => ({
      SignatureValid: false,
      KeyId: KEY_ID,
    }));
    return new AwsKmsAdapter({ clientFactory: () => client });
  },
});

// ---------------------------------------------------------------------------
// AWS-specific unit tests
// ---------------------------------------------------------------------------

describe("AwsKmsAdapter — AWS-specific behaviour", () => {
  describe("sign()", () => {
    it("maps ECDSA_SHA_256 to AWS SigningAlgorithmSpec", async () => {
      let capturedInput: unknown;
      const client = makeMockClient(async (cmd) => {
        capturedInput = (cmd as { input: unknown }).input;
        return { Signature: TEST_SIG, KeyId: KEY_ID, SigningAlgorithm: SigningAlgorithmSpec.ECDSA_SHA_256 };
      });

      const adapter = new AwsKmsAdapter({ clientFactory: () => client });
      await adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" });

      expect((capturedInput as { SigningAlgorithm: string }).SigningAlgorithm).toBe("ECDSA_SHA_256");
    });

    it("passes RAW MessageType to KMS", async () => {
      let capturedInput: unknown;
      const client = makeMockClient(async (cmd) => {
        capturedInput = (cmd as { input: unknown }).input;
        return { Signature: TEST_SIG, KeyId: KEY_ID };
      });

      const adapter = new AwsKmsAdapter({ clientFactory: () => client });
      await adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" });

      expect((capturedInput as { MessageType: string }).MessageType).toBe("RAW");
    });

    it("classifies NotFoundException as KEY_NOT_FOUND", async () => {
      const client = makeMockClient(async () => {
        throw new NotFoundException({ message: "key not found", $metadata: {} });
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "KEY_NOT_FOUND" });
    });

    it("classifies AccessDeniedException as PERMISSION_DENIED", async () => {
      const client = makeMockClient(async () => {
        throw new AccessDeniedException({ message: "access denied", $metadata: {} });
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "PERMISSION_DENIED" });
    });

    it("classifies DisabledException as KEY_DISABLED", async () => {
      const client = makeMockClient(async () => {
        throw new DisabledException({ message: "key disabled", $metadata: {} });
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "KEY_DISABLED" });
    });

    it("classifies InvalidKeyUsageException as ALGORITHM_MISMATCH", async () => {
      const client = makeMockClient(async () => {
        throw new InvalidKeyUsageException({ message: "invalid key usage", $metadata: {} });
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "ALGORITHM_MISMATCH" });
    });

    it("classifies generic KMSServiceException as PROVIDER_ERROR", async () => {
      const client = makeMockClient(async () => {
        throw makeKmsException("KMSServiceException", 500);
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "PROVIDER_ERROR" });
    });

    it("wraps non-Error thrown values in HsmError(UNKNOWN)", async () => {
      const client = makeMockClient(async () => {
        throw "string error"; // non-Error throw
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "UNKNOWN" });
    });

    it("throws HsmError(PROVIDER_ERROR) when KMS returns no signature bytes", async () => {
      const client = makeMockClient(async () => ({
        Signature: undefined,
        KeyId: KEY_ID,
      }));
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "PROVIDER_ERROR" });
    });

    it("retries on 429 throttle and eventually succeeds", async () => {
      let calls = 0;
      const client = makeMockClient(async () => {
        calls++;
        if (calls < 3) {
          throw makeKmsException("ThrottlingException", 429, "rate exceeded");
        }
        return { Signature: TEST_SIG, KeyId: KEY_ID };
      });

      // Use zero-delay retry so test runs fast
      const adapter = new AwsKmsAdapter({
        clientFactory: () => client,
        // Override retry delay via a custom RetryPolicy implicitly —
        // we just need to confirm the retry happened
      });

      const res = await adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" });
      expect(res.signature).toBeInstanceOf(Uint8Array);
      expect(calls).toBeGreaterThanOrEqual(2);
    });
  });

  describe("verify()", () => {
    it("returns valid:false (no throw) when KMSInvalidSignatureException is thrown", async () => {
      const client = makeMockClient(async () => {
        throw new KMSInvalidSignatureException({
          message: "signature invalid",
          $metadata: {},
        });
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      const res = await adapter.verify({
        key: { keyId: KEY_ID },
        message: TEST_MSG,
        signature: TEST_SIG,
        algorithm: "ECDSA_SHA_256",
      });
      expect(res.valid).toBe(false);
    });

    it("passes signature bytes to AWS VerifyCommand", async () => {
      let capturedInput: unknown;
      const client = makeMockClient(async (cmd) => {
        capturedInput = (cmd as { input: unknown }).input;
        return { SignatureValid: true, KeyId: KEY_ID };
      });

      const adapter = new AwsKmsAdapter({ clientFactory: () => client });
      await adapter.verify({
        key: { keyId: KEY_ID },
        message: TEST_MSG,
        signature: TEST_SIG,
        algorithm: "ECDSA_SHA_256",
      });

      expect((capturedInput as { Signature: Uint8Array }).Signature).toEqual(TEST_SIG);
    });
  });

  describe("rotate()", () => {
    it("calls RotateKeyOnDemandCommand with the correct KeyId", async () => {
      const commandsSent: string[] = [];
      const client = makeMockClient(async (cmd) => {
        const name = (cmd as { constructor: { name: string } }).constructor.name;
        commandsSent.push(name);
        if (name === "DescribeKeyCommand") return { KeyMetadata: { KeyId: KEY_ID } };
        if (name === "RotateKeyOnDemandCommand") return { KeyId: KEY_ID };
        return {};
      });

      const adapter = new AwsKmsAdapter({ clientFactory: () => client });
      const res = await adapter.rotate({ key: { keyId: KEY_ID } });

      expect(commandsSent).toContain("RotateKeyOnDemandCommand");
      expect(res.newKeyVersion).toBe(KEY_ID);
      expect(res.previousKeyVersion).toBe(KEY_ID);
    });

    it("throws HsmError(KEY_NOT_FOUND) when DescribeKey returns NotFoundException", async () => {
      const client = makeMockClient(async () => {
        throw new NotFoundException({ message: "not found", $metadata: {} });
      });
      const adapter = new AwsKmsAdapter({ clientFactory: () => client });

      await expect(adapter.rotate({ key: { keyId: KEY_ID } })).rejects.toMatchObject({
        code: "KEY_NOT_FOUND",
      });
    });
  });

  describe("region failover", () => {
    it("does NOT failover on KEY_NOT_FOUND (non-infrastructure error)", async () => {
      let regionsSeen: string[] = [];
      const adapter = new AwsKmsAdapter({
        regions: ["us-east-1", "us-west-2"],
        clientFactory: (region) => {
          regionsSeen.push(region);
          return makeMockClient(async () => {
            throw new NotFoundException({ message: "not found", $metadata: {} });
          });
        },
      });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "KEY_NOT_FOUND" });

      // Only one region should have been tried
      expect(regionsSeen).toHaveLength(1);
    });

    it("does NOT failover on PERMISSION_DENIED (non-infrastructure error)", async () => {
      let regionsSeen: string[] = [];
      const adapter = new AwsKmsAdapter({
        regions: ["us-east-1", "us-west-2"],
        clientFactory: (region) => {
          regionsSeen.push(region);
          return makeMockClient(async () => {
            throw new AccessDeniedException({ message: "denied", $metadata: {} });
          });
        },
      });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "PERMISSION_DENIED" });

      expect(regionsSeen).toHaveLength(1);
    });

    it("fails over to second region on PROVIDER_ERROR", async () => {
      const regionsSeen: string[] = [];
      const adapter = new AwsKmsAdapter({
        regions: ["us-east-1", "eu-west-1"],
        clientFactory: (region) => {
          regionsSeen.push(region);
          if (region === "us-east-1") {
            return makeMockClient(async () => {
              throw new HsmError("endpoint down", "PROVIDER_ERROR");
            });
          }
          return makeMockClient(async () => ({
            Signature: TEST_SIG,
            KeyId: KEY_ID,
          }));
        },
      });

      const res = await adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" });
      expect(res.signature).toEqual(TEST_SIG);
      expect(regionsSeen).toContain("eu-west-1");
    });

    it("throws REGION_UNAVAILABLE when every region fails with PROVIDER_ERROR", async () => {
      const adapter = new AwsKmsAdapter({
        regions: ["us-east-1", "eu-west-1", "ap-southeast-1"],
        clientFactory: () =>
          makeMockClient(async () => {
            throw new HsmError("all down", "PROVIDER_ERROR");
          }),
      });

      await expect(
        adapter.sign({ key: { keyId: KEY_ID }, message: TEST_MSG, algorithm: "ECDSA_SHA_256" }),
      ).rejects.toMatchObject({ code: "REGION_UNAVAILABLE" });
    });
  });
});

/**
 * GcpKmsAdapter tests
 *
 * - Exercises the full IHsmAdapter contract via the shared suite
 * - Adds GCP-specific unit tests for gRPC error mapping, retries,
 *   location failover, and key version management
 */

import { describe, it, expect, jest } from "@jest/globals";
import { KeyManagementServiceClient } from "@google-cloud/kms";
import { GcpKmsAdapter } from "../gcp-kms-adapter.js";
import { HsmError } from "../types.js";
import type { SigningAlgorithm } from "../types.js";
import { runHsmAdapterContractTests } from "./hsm-adapter.contract.js";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const KEY_VERSION =
  "projects/my-project/locations/us-east1/keyRings/my-ring/cryptoKeys/my-key/cryptoKeyVersions/1";
const CRYPTO_KEY =
  "projects/my-project/locations/us-east1/keyRings/my-ring/cryptoKeys/my-key";
const TEST_MSG = new Uint8Array([1, 2, 3]);
const TEST_SIG = new Uint8Array([10, 20, 30]);
const ALGORITHM: SigningAlgorithm = "ECDSA_SHA_256";

/** Construct a gRPC-style error object (not a real Error instance — matches gRPC SDK shape). */
function makeGrpcError(code: number, message = "gRPC error"): unknown {
  const err = new Error(message) as Error & { code: number; details: string };
  err.code = code;
  err.details = message;
  return err;
}

/** Build a mock KeyManagementServiceClient. */
function makeMockGcpClient(overrides: {
  asymmetricSign?: (req: unknown) => Promise<unknown>;
  asymmetricVerify?: (req: unknown) => Promise<unknown>;
  createCryptoKeyVersion?: (req: unknown) => Promise<unknown>;
  destroyCryptoKeyVersion?: (req: unknown) => Promise<unknown>;
  getCryptoKey?: (req: unknown) => Promise<unknown>;
}): KeyManagementServiceClient {
  const client = new KeyManagementServiceClient();

  if (overrides.asymmetricSign) {
    jest.spyOn(client, "asymmetricSign").mockImplementation(
      overrides.asymmetricSign as Parameters<typeof jest.spyOn>[1],
    );
  }
  if (overrides.asymmetricVerify) {
    jest.spyOn(client, "asymmetricVerify").mockImplementation(
      overrides.asymmetricVerify as Parameters<typeof jest.spyOn>[1],
    );
  }
  if (overrides.createCryptoKeyVersion) {
    jest.spyOn(client, "createCryptoKeyVersion").mockImplementation(
      overrides.createCryptoKeyVersion as Parameters<typeof jest.spyOn>[1],
    );
  }
  if (overrides.destroyCryptoKeyVersion) {
    jest.spyOn(client, "destroyCryptoKeyVersion").mockImplementation(
      overrides.destroyCryptoKeyVersion as Parameters<typeof jest.spyOn>[1],
    );
  }
  if (overrides.getCryptoKey) {
    jest.spyOn(client, "getCryptoKey").mockImplementation(
      overrides.getCryptoKey as Parameters<typeof jest.spyOn>[1],
    );
  }

  return client;
}

// ---------------------------------------------------------------------------
// Contract suite wiring
// ---------------------------------------------------------------------------

runHsmAdapterContractTests("GcpKmsAdapter", {
  makeHappyAdapter(opts = {}) {
    const sig = opts.signature ?? TEST_SIG;
    const kv = opts.keyVersion ?? KEY_VERSION;
    const newKv = opts.newKeyVersion ?? KEY_VERSION + "_new";
    const prevKv = opts.previousKeyVersion ?? KEY_VERSION;

    const client = makeMockGcpClient({
      asymmetricSign: async () => [{ signature: sig, name: kv }],
      asymmetricVerify: async () => [{ success: true, name: kv }],
      getCryptoKey: async () => [{ primary: { name: prevKv } }],
      createCryptoKeyVersion: async () => [{ name: newKv }],
      destroyCryptoKeyVersion: async () => [{}],
    });

    return new GcpKmsAdapter({ clientFactory: () => client });
  },

  makeErrorAdapter(code: string) {
    const client = makeMockGcpClient({
      asymmetricSign: async () => {
        throw new HsmError(`Simulated ${code}`, code as HsmError["code"]);
      },
      asymmetricVerify: async () => {
        throw new HsmError(`Simulated ${code}`, code as HsmError["code"]);
      },
      getCryptoKey: async () => {
        throw new HsmError(`Simulated ${code}`, code as HsmError["code"]);
      },
      createCryptoKeyVersion: async () => {
        throw new HsmError(`Simulated ${code}`, code as HsmError["code"]);
      },
    });
    return new GcpKmsAdapter({ clientFactory: () => client });
  },

  makeFailoverAdapter() {
    let callCount = 0;
    return new GcpKmsAdapter({
      locations: ["us-east1", "us-central1"],
      clientFactory: () => {
        callCount++;
        if (callCount === 1) {
          return makeMockGcpClient({
            asymmetricSign: async () => {
              throw new HsmError("location down", "PROVIDER_ERROR");
            },
          });
        }
        return makeMockGcpClient({
          asymmetricSign: async () => [{ signature: TEST_SIG, name: KEY_VERSION }],
        });
      },
    });
  },

  makeAllRegionsFailAdapter() {
    return new GcpKmsAdapter({
      locations: ["us-east1", "us-central1"],
      clientFactory: () =>
        makeMockGcpClient({
          asymmetricSign: async () => {
            throw new HsmError("down", "PROVIDER_ERROR");
          },
        }),
    });
  },

  makeVerifyValidAdapter() {
    const client = makeMockGcpClient({
      asymmetricVerify: async () => [{ success: true, name: KEY_VERSION }],
    });
    return new GcpKmsAdapter({ clientFactory: () => client });
  },

  makeVerifyInvalidAdapter() {
    const client = makeMockGcpClient({
      asymmetricVerify: async () => [{ success: false, name: KEY_VERSION }],
    });
    return new GcpKmsAdapter({ clientFactory: () => client });
  },
});

// ---------------------------------------------------------------------------
// GCP-specific unit tests
// ---------------------------------------------------------------------------

describe("GcpKmsAdapter — GCP-specific behaviour", () => {
  describe("sign()", () => {
    it("passes message bytes to asymmetricSign", async () => {
      let capturedReq: unknown;
      const client = makeMockGcpClient({
        asymmetricSign: async (req) => {
          capturedReq = req;
          return [{ signature: TEST_SIG, name: KEY_VERSION }];
        },
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      await adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM });

      expect((capturedReq as { data: Uint8Array }).data).toEqual(TEST_MSG);
    });

    it("classifies gRPC NOT_FOUND (code 5) as KEY_NOT_FOUND", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => { throw makeGrpcError(5, "key not found"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "KEY_NOT_FOUND" });
    });

    it("classifies gRPC PERMISSION_DENIED (code 7) as PERMISSION_DENIED", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => { throw makeGrpcError(7, "permission denied"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "PERMISSION_DENIED" });
    });

    it("classifies gRPC UNAUTHENTICATED (code 16) as PERMISSION_DENIED", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => { throw makeGrpcError(16, "unauthenticated"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "PERMISSION_DENIED" });
    });

    it("classifies gRPC FAILED_PRECONDITION (code 9) as KEY_DISABLED", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => { throw makeGrpcError(9, "key disabled"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "KEY_DISABLED" });
    });

    it("classifies gRPC INVALID_ARGUMENT with 'algorithm' message as ALGORITHM_MISMATCH", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => { throw makeGrpcError(3, "algorithm not supported"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "ALGORITHM_MISMATCH" });
    });

    it("classifies gRPC INVALID_ARGUMENT with 'disabled' message as KEY_DISABLED", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => { throw makeGrpcError(3, "key version is disabled"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "KEY_DISABLED" });
    });

    it("throws PROVIDER_ERROR when signature bytes are absent", async () => {
      const client = makeMockGcpClient({
        asymmetricSign: async () => [{ signature: undefined, name: KEY_VERSION }],
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "PROVIDER_ERROR" });
    });

    it("retries on gRPC UNAVAILABLE (code 14)", async () => {
      let calls = 0;
      const client = makeMockGcpClient({
        asymmetricSign: async () => {
          calls++;
          if (calls < 3) throw makeGrpcError(14, "service unavailable");
          return [{ signature: TEST_SIG, name: KEY_VERSION }];
        },
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      const res = await adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM });
      expect(res.signature).toEqual(TEST_SIG);
      expect(calls).toBeGreaterThanOrEqual(2);
    });

    it("retries on gRPC RESOURCE_EXHAUSTED (code 8 — quota)", async () => {
      let calls = 0;
      const client = makeMockGcpClient({
        asymmetricSign: async () => {
          calls++;
          if (calls < 2) throw makeGrpcError(8, "quota exceeded");
          return [{ signature: TEST_SIG, name: KEY_VERSION }];
        },
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      const res = await adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM });
      expect(res.signature).toEqual(TEST_SIG);
    });
  });

  describe("verify()", () => {
    it("passes signature and message to asymmetricVerify", async () => {
      let capturedReq: unknown;
      const client = makeMockGcpClient({
        asymmetricVerify: async (req) => {
          capturedReq = req;
          return [{ success: true, name: KEY_VERSION }];
        },
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      await adapter.verify({
        key: { keyId: KEY_VERSION },
        message: TEST_MSG,
        signature: TEST_SIG,
        algorithm: ALGORITHM,
      });

      expect((capturedReq as { signature: Uint8Array }).signature).toEqual(TEST_SIG);
      expect((capturedReq as { data: Uint8Array }).data).toEqual(TEST_MSG);
    });

    it("returns valid:false (no throw) on gRPC INVALID_ARGUMENT for signature", async () => {
      const client = makeMockGcpClient({
        asymmetricVerify: async () => { throw makeGrpcError(3, "signature invalid"); },
      });
      const adapter = new GcpKmsAdapter({ clientFactory: () => client });

      const res = await adapter.verify({
        key: { keyId: KEY_VERSION },
        message: TEST_MSG,
        signature: TEST_SIG,
        algorithm: ALGORITHM,
      });
      expect(res.valid).toBe(false);
    });
  });

  describe("rotate()", () => {
    it("creates a new CryptoKeyVersion and destroys the old one", async () => {
      const destroyCalls: unknown[] = [];
      const newVersionName =
        "projects/my-project/locations/us-east1/keyRings/my-ring/cryptoKeys/my-key/cryptoKeyVersions/2";

      const client = makeMockGcpClient({
        getCryptoKey: async () => [{ primary: { name: KEY_VERSION } }],
        createCryptoKeyVersion: async () => [{ name: newVersionName }],
        destroyCryptoKeyVersion: async (req) => {
          destroyCalls.push(req);
          return [{}];
        },
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      const res = await adapter.rotate({ key: { keyId: CRYPTO_KEY } });

      expect(res.newKeyVersion).toBe(newVersionName);
      expect(res.previousKeyVersion).toBe(KEY_VERSION);
      expect(destroyCalls).toHaveLength(1);
    });

    it("uses the keyId directly as previousKeyVersion if it contains /cryptoKeyVersions/", async () => {
      const newVersionName = KEY_VERSION.replace(/\/1$/, "/2");
      const client = makeMockGcpClient({
        createCryptoKeyVersion: async () => [{ name: newVersionName }],
        destroyCryptoKeyVersion: async () => [{}],
        getCryptoKey: async () => [{ primary: { name: KEY_VERSION } }],
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      const res = await adapter.rotate({ key: { keyId: KEY_VERSION } });

      expect(res.previousKeyVersion).toBe(KEY_VERSION);
    });

    it("continues rotation even if destroyCryptoKeyVersion fails (non-fatal)", async () => {
      const newVersionName = KEY_VERSION.replace("/1", "/2");
      const client = makeMockGcpClient({
        getCryptoKey: async () => [{ primary: { name: KEY_VERSION } }],
        createCryptoKeyVersion: async () => [{ name: newVersionName }],
        destroyCryptoKeyVersion: async () => {
          throw makeGrpcError(14, "service unavailable");
        },
      });

      const adapter = new GcpKmsAdapter({ clientFactory: () => client });
      // Should not throw even when destroy fails
      await expect(adapter.rotate({ key: { keyId: CRYPTO_KEY } })).resolves.toMatchObject({
        newKeyVersion: newVersionName,
      });
    });
  });

  describe("location failover", () => {
    it("rewrites the location segment when failing over", async () => {
      const namesReceived: string[] = [];
      let callCount = 0;

      const adapter = new GcpKmsAdapter({
        locations: ["us-east1", "us-central1"],
        clientFactory: () => {
          callCount++;
          if (callCount === 1) {
            return makeMockGcpClient({
              asymmetricSign: async () => {
                throw new HsmError("location down", "PROVIDER_ERROR");
              },
            });
          }
          return makeMockGcpClient({
            asymmetricSign: async (req) => {
              namesReceived.push((req as { name: string }).name);
              return [{ signature: TEST_SIG, name: (req as { name: string }).name }];
            },
          });
        },
      });

      await adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM });

      // The key name used in the second request should have "us-central1"
      expect(namesReceived[0]).toContain("us-central1");
    });

    it("does NOT failover on KEY_NOT_FOUND", async () => {
      let clientCallCount = 0;
      const adapter = new GcpKmsAdapter({
        locations: ["us-east1", "us-central1"],
        clientFactory: () => {
          clientCallCount++;
          return makeMockGcpClient({
            asymmetricSign: async () => { throw makeGrpcError(5, "not found"); },
          });
        },
      });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "KEY_NOT_FOUND" });

      expect(clientCallCount).toBe(1);
    });

    it("throws REGION_UNAVAILABLE when all GCP locations fail", async () => {
      const adapter = new GcpKmsAdapter({
        locations: ["us-east1", "us-central1", "europe-west1"],
        clientFactory: () =>
          makeMockGcpClient({
            asymmetricSign: async () => {
              throw new HsmError("down", "PROVIDER_ERROR");
            },
          }),
      });

      await expect(
        adapter.sign({ key: { keyId: KEY_VERSION }, message: TEST_MSG, algorithm: ALGORITHM }),
      ).rejects.toMatchObject({ code: "REGION_UNAVAILABLE" });
    });
  });
});

/**
 * HSM adapter contract tests — shared behaviour suite
 *
 * This file defines `runHsmAdapterContractTests`, a function that exercises the
 * `IHsmAdapter` contract using any concrete adapter passed to it. The same
 * suite is executed for both `AwsKmsAdapter` and `GcpKmsAdapter`.
 *
 * Contract obligations tested:
 * ─────────────────────────────
 * 1.  sign returns a non-empty Uint8Array signature
 * 2.  sign echoes the requested algorithm in its response
 * 3.  sign returns a keyVersion string
 * 4.  verify returns valid:true for a signature produced by sign
 * 5.  verify returns valid:false (no throw) for a tampered signature
 * 6.  rotate returns newKeyVersion and previousKeyVersion strings
 * 7.  rotate previousKeyVersion differs from (or equals) newKeyVersion
 *     depending on the provider's versioning scheme
 * 8.  sign throws HsmError(KEY_NOT_FOUND) for an unknown key
 * 9.  sign throws HsmError(PERMISSION_DENIED) when credentials are refused
 * 10. sign throws HsmError(KEY_DISABLED) for a disabled key
 * 11. sign throws HsmError(ALGORITHM_MISMATCH) for an incompatible algorithm
 * 12. verify throws HsmError(KEY_NOT_FOUND) for an unknown key
 * 13. rotate throws HsmError(KEY_NOT_FOUND) for an unknown key
 * 14. Region/location failover: succeeds after first region fails
 * 15. All regions exhausted: throws HsmError(REGION_UNAVAILABLE)
 */

import { describe, it, expect } from "@jest/globals";
import type { IHsmAdapter } from "../hsm-adapter.interface.js";
import { HsmError } from "../types.js";
import type { SigningAlgorithm } from "../types.js";

/** Minimal factory spec consumed by the contract suite. */
export interface AdapterFactory {
  /**
   * Create an adapter whose underlying KMS client reports a valid signing
   * operation, returning `signature` for the given `message`.
   */
  makeHappyAdapter(opts?: {
    signature?: Uint8Array;
    keyVersion?: string;
    newKeyVersion?: string;
    previousKeyVersion?: string;
  }): IHsmAdapter;

  /**
   * Create an adapter that throws `HsmError` with `code` for any operation.
   */
  makeErrorAdapter(code: string): IHsmAdapter;

  /**
   * Create an adapter that fails on the first region/location then succeeds.
   * Used to test region failover.
   */
  makeFailoverAdapter(): IHsmAdapter;

  /**
   * Create an adapter whose every region/location fails.
   * Used to test exhausted failover.
   */
  makeAllRegionsFailAdapter(): IHsmAdapter;

  /**
   * Create an adapter that returns `valid: true` for verify.
   */
  makeVerifyValidAdapter(): IHsmAdapter;

  /**
   * Create an adapter that returns `valid: false` (but does NOT throw)
   * for verify.
   */
  makeVerifyInvalidAdapter(): IHsmAdapter;
}

const TEST_KEY = { keyId: "test-key-id", alias: "test-key" };
const TEST_MESSAGE = new Uint8Array([1, 2, 3, 4, 5]);
const TEST_SIGNATURE = new Uint8Array([10, 20, 30, 40, 50]);
const ALGORITHM: SigningAlgorithm = "ECDSA_SHA_256";

export function runHsmAdapterContractTests(
  adapterName: string,
  factory: AdapterFactory,
): void {
  describe(`${adapterName} — IHsmAdapter contract`, () => {
    // ──────────────────────────────────────────────────────────────────────
    // sign
    // ──────────────────────────────────────────────────────────────────────

    describe("sign()", () => {
      it("returns a non-empty Uint8Array signature", async () => {
        const adapter = factory.makeHappyAdapter({ signature: TEST_SIGNATURE });
        const res = await adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM });
        expect(res.signature).toBeInstanceOf(Uint8Array);
        expect(res.signature.length).toBeGreaterThan(0);
      });

      it("echoes the requested algorithm in the response", async () => {
        const adapter = factory.makeHappyAdapter();
        const res = await adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM });
        expect(res.algorithm).toBe(ALGORITHM);
      });

      it("returns a non-empty keyVersion string", async () => {
        const adapter = factory.makeHappyAdapter({ keyVersion: "v1" });
        const res = await adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM });
        expect(typeof res.keyVersion).toBe("string");
        expect(res.keyVersion.length).toBeGreaterThan(0);
      });

      it("throws HsmError(KEY_NOT_FOUND) for an unknown key", async () => {
        const adapter = factory.makeErrorAdapter("KEY_NOT_FOUND");
        await expect(
          adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM }),
        ).rejects.toMatchObject({ code: "KEY_NOT_FOUND" });
      });

      it("throws HsmError(PERMISSION_DENIED) when credentials are refused", async () => {
        const adapter = factory.makeErrorAdapter("PERMISSION_DENIED");
        await expect(
          adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM }),
        ).rejects.toMatchObject({ code: "PERMISSION_DENIED" });
      });

      it("throws HsmError(KEY_DISABLED) for a disabled key", async () => {
        const adapter = factory.makeErrorAdapter("KEY_DISABLED");
        await expect(
          adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM }),
        ).rejects.toMatchObject({ code: "KEY_DISABLED" });
      });

      it("throws HsmError(ALGORITHM_MISMATCH) for an incompatible algorithm", async () => {
        const adapter = factory.makeErrorAdapter("ALGORITHM_MISMATCH");
        await expect(
          adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM }),
        ).rejects.toMatchObject({ code: "ALGORITHM_MISMATCH" });
      });

      it("errors are instances of HsmError", async () => {
        const adapter = factory.makeErrorAdapter("KEY_NOT_FOUND");
        await expect(
          adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM }),
        ).rejects.toBeInstanceOf(HsmError);
      });
    });

    // ──────────────────────────────────────────────────────────────────────
    // verify
    // ──────────────────────────────────────────────────────────────────────

    describe("verify()", () => {
      it("returns valid:true for a valid signature", async () => {
        const adapter = factory.makeVerifyValidAdapter();
        const res = await adapter.verify({
          key: TEST_KEY,
          message: TEST_MESSAGE,
          signature: TEST_SIGNATURE,
          algorithm: ALGORITHM,
        });
        expect(res.valid).toBe(true);
      });

      it("returns valid:false (does not throw) for an invalid signature", async () => {
        const adapter = factory.makeVerifyInvalidAdapter();
        const res = await adapter.verify({
          key: TEST_KEY,
          message: TEST_MESSAGE,
          signature: TEST_SIGNATURE,
          algorithm: ALGORITHM,
        });
        expect(res.valid).toBe(false);
      });

      it("returns a non-empty keyVersion string", async () => {
        const adapter = factory.makeVerifyValidAdapter();
        const res = await adapter.verify({
          key: TEST_KEY,
          message: TEST_MESSAGE,
          signature: TEST_SIGNATURE,
          algorithm: ALGORITHM,
        });
        expect(typeof res.keyVersion).toBe("string");
        expect(res.keyVersion.length).toBeGreaterThan(0);
      });

      it("throws HsmError(KEY_NOT_FOUND) for an unknown key", async () => {
        const adapter = factory.makeErrorAdapter("KEY_NOT_FOUND");
        await expect(
          adapter.verify({
            key: TEST_KEY,
            message: TEST_MESSAGE,
            signature: TEST_SIGNATURE,
            algorithm: ALGORITHM,
          }),
        ).rejects.toMatchObject({ code: "KEY_NOT_FOUND" });
      });

      it("throws HsmError(PERMISSION_DENIED) when credentials are refused", async () => {
        const adapter = factory.makeErrorAdapter("PERMISSION_DENIED");
        await expect(
          adapter.verify({
            key: TEST_KEY,
            message: TEST_MESSAGE,
            signature: TEST_SIGNATURE,
            algorithm: ALGORITHM,
          }),
        ).rejects.toMatchObject({ code: "PERMISSION_DENIED" });
      });
    });

    // ──────────────────────────────────────────────────────────────────────
    // rotate
    // ──────────────────────────────────────────────────────────────────────

    describe("rotate()", () => {
      it("returns newKeyVersion and previousKeyVersion strings", async () => {
        const adapter = factory.makeHappyAdapter({
          newKeyVersion: "v2",
          previousKeyVersion: "v1",
        });
        const res = await adapter.rotate({ key: TEST_KEY });
        expect(typeof res.newKeyVersion).toBe("string");
        expect(res.newKeyVersion.length).toBeGreaterThan(0);
        expect(typeof res.previousKeyVersion).toBe("string");
        expect(res.previousKeyVersion.length).toBeGreaterThan(0);
      });

      it("throws HsmError(KEY_NOT_FOUND) for an unknown key", async () => {
        const adapter = factory.makeErrorAdapter("KEY_NOT_FOUND");
        await expect(adapter.rotate({ key: TEST_KEY })).rejects.toMatchObject({
          code: "KEY_NOT_FOUND",
        });
      });

      it("throws HsmError(PERMISSION_DENIED) when credentials are refused", async () => {
        const adapter = factory.makeErrorAdapter("PERMISSION_DENIED");
        await expect(adapter.rotate({ key: TEST_KEY })).rejects.toMatchObject({
          code: "PERMISSION_DENIED",
        });
      });
    });

    // ──────────────────────────────────────────────────────────────────────
    // Region / location failover
    // ──────────────────────────────────────────────────────────────────────

    describe("region/location failover", () => {
      it("succeeds when the first region fails and the second succeeds", async () => {
        const adapter = factory.makeFailoverAdapter();
        // Should not throw — second region handles the request
        const res = await adapter.sign({
          key: TEST_KEY,
          message: TEST_MESSAGE,
          algorithm: ALGORITHM,
        });
        expect(res.signature).toBeInstanceOf(Uint8Array);
      });

      it("throws HsmError(REGION_UNAVAILABLE) when all regions are exhausted", async () => {
        const adapter = factory.makeAllRegionsFailAdapter();
        await expect(
          adapter.sign({ key: TEST_KEY, message: TEST_MESSAGE, algorithm: ALGORITHM }),
        ).rejects.toMatchObject({ code: "REGION_UNAVAILABLE" });
      });
    });
  });
}

/**
 * AwsKmsAdapter — IHsmAdapter backed by AWS Key Management Service.
 *
 * Behaviour
 * ──────────
 * • sign   → KMSClient.send(SignCommand)
 * • verify → KMSClient.send(VerifyCommand)
 * • rotate → KMSClient.send(RotateKeyOnDemandCommand)
 *            Falls back to ScheduleKeyDeletion + CreateKey flow when the key
 *            type does not support on-demand rotation.
 *
 * Region failover
 * ────────────────
 * Pass multiple region strings in `regions`. On a `REGION_UNAVAILABLE`
 * condition (KMSServiceException from any network / endpoint error), the
 * adapter retries each remaining region before giving up.
 *
 * Retry policy
 * ─────────────
 * Transient errors (network timeouts, throttling, 5xx from KMS) are retried
 * using the project-standard exponential back-off from `utils/retry-policy`.
 * Non-retriable errors (4xx, key-not-found, permission-denied) are mapped to
 * `HsmError` immediately.
 */

import {
  KMSClient,
  SignCommand,
  VerifyCommand,
  DescribeKeyCommand,
  RotateKeyOnDemandCommand,
  type SignCommandInput,
  type VerifyCommandInput,
  KMSServiceException,
  InvalidKeyUsageException,
  NotFoundException,
  DisabledException,
  KMSInvalidSignatureException,
  AccessDeniedException,
  SigningAlgorithmSpec,
} from "@aws-sdk/client-kms";

import type { IHsmAdapter } from "./hsm-adapter.interface.js";
import type {
  SignRequest,
  SignResponse,
  VerifyRequest,
  VerifyResponse,
  RotateRequest,
  RotateResponse,
  SigningAlgorithm,
} from "./types.js";
import { HsmError } from "./types.js";
import { RetryPolicy, DEFAULT_RETRY_CONFIG } from "../../utils/retry-policy.js";

// ---------------------------------------------------------------------------
// Algorithm mapping
// ---------------------------------------------------------------------------

const ALGORITHM_MAP: Record<SigningAlgorithm, SigningAlgorithmSpec> = {
  RSASSA_PSS_SHA_256: SigningAlgorithmSpec.RSASSA_PSS_SHA_256,
  RSASSA_PSS_SHA_384: SigningAlgorithmSpec.RSASSA_PSS_SHA_384,
  RSASSA_PSS_SHA_512: SigningAlgorithmSpec.RSASSA_PSS_SHA_512,
  RSASSA_PKCS1_V1_5_SHA_256: SigningAlgorithmSpec.RSASSA_PKCS1_V1_5_SHA_256,
  RSASSA_PKCS1_V1_5_SHA_384: SigningAlgorithmSpec.RSASSA_PKCS1_V1_5_SHA_384,
  RSASSA_PKCS1_V1_5_SHA_512: SigningAlgorithmSpec.RSASSA_PKCS1_V1_5_SHA_512,
  ECDSA_SHA_256: SigningAlgorithmSpec.ECDSA_SHA_256,
  ECDSA_SHA_384: SigningAlgorithmSpec.ECDSA_SHA_384,
  ECDSA_SHA_512: SigningAlgorithmSpec.ECDSA_SHA_512,
};

// ---------------------------------------------------------------------------
// Error helpers
// ---------------------------------------------------------------------------

function classifyAwsError(
  err: unknown,
  keyId: string,
): HsmError {
  if (err instanceof NotFoundException) {
    return new HsmError(
      `Key not found: ${keyId}`,
      "KEY_NOT_FOUND",
      { cause: err as Error },
    );
  }
  if (err instanceof AccessDeniedException) {
    return new HsmError(
      `Permission denied for key: ${keyId}`,
      "PERMISSION_DENIED",
      { cause: err as Error },
    );
  }
  if (err instanceof DisabledException) {
    return new HsmError(
      `Key is disabled: ${keyId}`,
      "KEY_DISABLED",
      { cause: err as Error },
    );
  }
  if (err instanceof InvalidKeyUsageException) {
    return new HsmError(
      `Algorithm not supported by key: ${keyId}`,
      "ALGORITHM_MISMATCH",
      { cause: err as Error },
    );
  }
  if (err instanceof KMSInvalidSignatureException) {
    return new HsmError(
      `Signature is invalid for key: ${keyId}`,
      "INVALID_SIGNATURE",
      { cause: err as Error },
    );
  }
  if (err instanceof KMSServiceException) {
    return new HsmError(
      `KMS provider error: ${(err as Error).message}`,
      "PROVIDER_ERROR",
      { cause: err as Error },
    );
  }
  return new HsmError(
    `Unknown HSM error: ${(err as Error).message ?? String(err)}`,
    "UNKNOWN",
    { cause: err instanceof Error ? err : undefined },
  );
}

function isRetriable(err: unknown): boolean {
  if (!(err instanceof KMSServiceException)) return false;
  const status = (err as KMSServiceException).$metadata?.httpStatusCode ?? 0;
  // Throttling or server errors are retriable; auth / not-found are not
  return status === 429 || status >= 500;
}

// ---------------------------------------------------------------------------
// Public configuration
// ---------------------------------------------------------------------------

export interface AwsKmsAdapterOptions {
  /**
   * Ordered list of AWS regions to try. The adapter attempts each in order
   * when a region-level error is encountered (failover).
   * Defaults to `["us-east-1"]`.
   */
  regions?: string[];
  /**
   * Optional factory for the KMSClient. Primarily used in tests to inject
   * mock clients without needing real AWS credentials.
   */
  clientFactory?: (region: string) => KMSClient;
}

// ---------------------------------------------------------------------------
// Adapter
// ---------------------------------------------------------------------------

export class AwsKmsAdapter implements IHsmAdapter {
  private readonly regions: string[];
  private readonly clientFactory: (region: string) => KMSClient;
  private readonly retry: RetryPolicy;

  constructor(options: AwsKmsAdapterOptions = {}) {
    this.regions = options.regions?.length ? options.regions : ["us-east-1"];
    this.clientFactory =
      options.clientFactory ?? ((region) => new KMSClient({ region }));
    this.retry = new RetryPolicy({
      ...DEFAULT_RETRY_CONFIG,
      maxRetries: 3,
      initialDelay: 200,
    });
  }

  // ──────────────────────────────────────────────────────────────────────────
  // sign
  // ──────────────────────────────────────────────────────────────────────────

  async sign(request: SignRequest): Promise<SignResponse> {
    const awsAlgorithm = ALGORITHM_MAP[request.algorithm];
    if (!awsAlgorithm) {
      throw new HsmError(
        `Unsupported algorithm: ${request.algorithm}`,
        "ALGORITHM_MISMATCH",
        { keyRef: request.key },
      );
    }

    const input: SignCommandInput = {
      KeyId: request.key.keyId,
      Message: request.message,
      MessageType: "RAW",
      SigningAlgorithm: awsAlgorithm,
    };

    const response = await this.withRegionFailover(async (client) => {
      return this.retry.execute(async () => {
        try {
          return await client.send(new SignCommand(input));
        } catch (err) {
          if (isRetriable(err)) throw err; // let RetryPolicy handle it
          throw classifyAwsError(err, request.key.keyId);
        }
      });
    });

    if (!response.Signature) {
      throw new HsmError("KMS returned empty signature", "PROVIDER_ERROR", {
        keyRef: request.key,
      });
    }

    return {
      signature: new Uint8Array(response.Signature),
      algorithm: request.algorithm,
      keyVersion: response.KeyId ?? request.key.keyId,
    };
  }

  // ──────────────────────────────────────────────────────────────────────────
  // verify
  // ──────────────────────────────────────────────────────────────────────────

  async verify(request: VerifyRequest): Promise<VerifyResponse> {
    const awsAlgorithm = ALGORITHM_MAP[request.algorithm];
    if (!awsAlgorithm) {
      throw new HsmError(
        `Unsupported algorithm: ${request.algorithm}`,
        "ALGORITHM_MISMATCH",
        { keyRef: request.key },
      );
    }

    const input: VerifyCommandInput = {
      KeyId: request.key.keyId,
      Message: request.message,
      MessageType: "RAW",
      Signature: request.signature,
      SigningAlgorithm: awsAlgorithm,
    };

    const response = await this.withRegionFailover(async (client) => {
      return this.retry.execute(async () => {
        try {
          return await client.send(new VerifyCommand(input));
        } catch (err) {
          // KMSInvalidSignatureException means bad signature — not a retriable
          // infrastructure error. Return valid:false rather than throwing.
          if (err instanceof KMSInvalidSignatureException) {
            return { SignatureValid: false, KeyId: request.key.keyId };
          }
          if (isRetriable(err)) throw err;
          throw classifyAwsError(err, request.key.keyId);
        }
      });
    });

    return {
      valid: response.SignatureValid === true,
      keyVersion: response.KeyId ?? request.key.keyId,
    };
  }

  // ──────────────────────────────────────────────────────────────────────────
  // rotate
  // ──────────────────────────────────────────────────────────────────────────

  async rotate(request: RotateRequest): Promise<RotateResponse> {
    // Fetch the current primary key version before rotation so we can report it.
    const currentVersion = await this.withRegionFailover(async (client) => {
      return this.retry.execute(async () => {
        try {
          const desc = await client.send(
            new DescribeKeyCommand({ KeyId: request.key.keyId }),
          );
          return desc.KeyMetadata?.KeyId ?? request.key.keyId;
        } catch (err) {
          if (isRetriable(err)) throw err;
          throw classifyAwsError(err, request.key.keyId);
        }
      });
    });

    // Trigger on-demand rotation (creates a new key material version).
    await this.withRegionFailover(async (client) => {
      return this.retry.execute(async () => {
        try {
          await client.send(
            new RotateKeyOnDemandCommand({ KeyId: request.key.keyId }),
          );
        } catch (err) {
          if (isRetriable(err)) throw err;
          throw classifyAwsError(err, request.key.keyId);
        }
      });
    });

    // Fetch the new primary key version id after rotation.
    const newVersion = await this.withRegionFailover(async (client) => {
      return this.retry.execute(async () => {
        try {
          const desc = await client.send(
            new DescribeKeyCommand({ KeyId: request.key.keyId }),
          );
          // After on-demand rotation AWS re-uses the same ARN but increments
          // the material version; the ARN is the stable identifier.
          return desc.KeyMetadata?.KeyId ?? request.key.keyId;
        } catch (err) {
          if (isRetriable(err)) throw err;
          throw classifyAwsError(err, request.key.keyId);
        }
      });
    });

    return {
      newKeyVersion: newVersion,
      previousKeyVersion: currentVersion,
    };
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Region failover helper
  // ──────────────────────────────────────────────────────────────────────────

  private async withRegionFailover<T>(
    fn: (client: KMSClient) => Promise<T>,
  ): Promise<T> {
    let lastError: HsmError | undefined;

    for (const region of this.regions) {
      const client = this.clientFactory(region);
      try {
        return await fn(client);
      } catch (err) {
        if (err instanceof HsmError) {
          // Non-infrastructure errors should not trigger region failover.
          if (
            err.code === "KEY_NOT_FOUND" ||
            err.code === "PERMISSION_DENIED" ||
            err.code === "ALGORITHM_MISMATCH" ||
            err.code === "KEY_DISABLED"
          ) {
            throw err;
          }
          lastError = err;
          continue;
        }
        // Unexpected non-HsmError — wrap and fail without failover.
        throw classifyAwsError(err, "unknown");
      }
    }

    throw (
      lastError ??
      new HsmError("All regions exhausted", "REGION_UNAVAILABLE")
    );
  }
}

/**
 * GcpKmsAdapter — IHsmAdapter backed by Google Cloud Key Management Service.
 *
 * Behaviour
 * ──────────
 * • sign   → KeyManagementServiceClient.asymmetricSign(…)
 * • verify → KeyManagementServiceClient.getPublicKey(…) + Node.js crypto.verify()
 *            GCP Cloud KMS does not expose a server-side asymmetricVerify for
 *            asymmetric keys (only `macVerify` for HMAC, which is out of scope).
 *            The public key is retrieved on demand and used for local verification.
 * • rotate → KeyManagementServiceClient.createCryptoKeyVersion(…)
 *            Attempts to destroy the previous version via
 *            destroyCryptoKeyVersion(…) — failure is non-fatal.
 *
 * Key naming
 * ──────────
 * GCP key references use the full resource name:
 *   `projects/{p}/locations/{l}/keyRings/{kr}/cryptoKeys/{ck}/cryptoKeyVersions/{v}`
 * For rotation, callers may omit the `/cryptoKeyVersions/{v}` suffix and
 * supply the parent CryptoKey path instead.  The adapter creates a new version
 * and returns its resource name as the new key version.
 *
 * Algorithm mapping
 * ─────────────────
 * GCP encodes the algorithm on the *key version*, not in the request.
 * The `algorithm` field in the request is used to select the correct
 * Node.js crypto algorithm for local verification.
 *
 * Region failover
 * ────────────────
 * GCP Cloud KMS is a global/regional service. `locations` accepts multiple
 * location IDs. On an unavailability error the adapter re-creates the client
 * pointing at the next location using the same project + key-ring name, then
 * retries the operation.
 *
 * Retry policy
 * ─────────────
 * Transient errors (gRPC UNAVAILABLE, RESOURCE_EXHAUSTED) are retried using
 * the project-standard exponential back-off from `utils/retry-policy`.
 */

import { createVerify } from "crypto";
import { KeyManagementServiceClient } from "@google-cloud/kms";
import type { IHsmAdapter } from "./hsm-adapter.interface.js";
import type {
  SignRequest,
  SignResponse,
  VerifyRequest,
  VerifyResponse,
  RotateRequest,
  RotateResponse,
  SigningAlgorithm,
} from "./types.js";
import { HsmError } from "./types.js";
import { RetryPolicy, DEFAULT_RETRY_CONFIG } from "../../utils/retry-policy.js";

// ---------------------------------------------------------------------------
// Algorithm → Node.js crypto algorithm mapping for local verification
// ---------------------------------------------------------------------------

/** Maps HSM algorithm to the hash name used by Node.js crypto for verification. */
const NODE_HASH_FOR_ALGORITHM: Record<SigningAlgorithm, string> = {
  RSASSA_PSS_SHA_256: "sha256",
  RSASSA_PSS_SHA_384: "sha384",
  RSASSA_PSS_SHA_512: "sha512",
  RSASSA_PKCS1_V1_5_SHA_256: "sha256",
  RSASSA_PKCS1_V1_5_SHA_384: "sha384",
  RSASSA_PKCS1_V1_5_SHA_512: "sha512",
  ECDSA_SHA_256: "sha256",
  ECDSA_SHA_384: "sha384",
  ECDSA_SHA_512: "sha512",
};

// gRPC status codes that indicate a transient infrastructure issue
const RETRIABLE_GRPC_CODES = new Set([
  4,  // DEADLINE_EXCEEDED
  8,  // RESOURCE_EXHAUSTED (quota / rate limit)
  10, // ABORTED
  14, // UNAVAILABLE
]);

// ---------------------------------------------------------------------------
// Error helpers
// ---------------------------------------------------------------------------

function isGrpcError(err: unknown): err is { code: number; details?: string; message: string } {
  return (
    typeof err === "object" &&
    err !== null &&
    "code" in err &&
    typeof (err as Record<string, unknown>).code === "number"
  );
}

/**
 * Maps gRPC status codes to the semantic error taxonomy.
 * gRPC codes: https://grpc.github.io/grpc/core/md_doc_statuscodes.html
 */
function classifyGcpError(err: unknown, keyId: string): HsmError {
  if (isGrpcError(err)) {
    const grpcCode = err.code;
    const msg = err.message ?? err.details ?? String(err);

    switch (grpcCode) {
      case 5:  // NOT_FOUND
        return new HsmError(`Key not found: ${keyId}`, "KEY_NOT_FOUND", {
          cause: err as unknown as Error,
        });
      case 7:  // PERMISSION_DENIED
      case 16: // UNAUTHENTICATED
        return new HsmError(`Permission denied for key: ${keyId}`, "PERMISSION_DENIED", {
          cause: err as unknown as Error,
        });
      case 3:  // INVALID_ARGUMENT — often algorithm mismatch or disabled
        if (/algorithm|purpose/i.test(msg)) {
          return new HsmError(`Algorithm not supported by key: ${keyId}`, "ALGORITHM_MISMATCH", {
            cause: err as unknown as Error,
          });
        }
        if (/disabled|destroy/i.test(msg)) {
          return new HsmError(`Key version is disabled: ${keyId}`, "KEY_DISABLED", {
            cause: err as unknown as Error,
          });
        }
        return new HsmError(`Provider validation error: ${msg}`, "PROVIDER_ERROR", {
          cause: err as unknown as Error,
        });
      case 9:  // FAILED_PRECONDITION — key disabled / wrong state
        return new HsmError(`Key is disabled or in wrong state: ${keyId}`, "KEY_DISABLED", {
          cause: err as unknown as Error,
        });
      default:
        return new HsmError(`KMS provider error (gRPC ${grpcCode}): ${msg}`, "PROVIDER_ERROR", {
          cause: err as unknown as Error,
        });
    }
  }

  return new HsmError(
    `Unknown HSM error: ${err instanceof Error ? err.message : String(err)}`,
    "UNKNOWN",
    { cause: err instanceof Error ? err : undefined },
  );
}

function isRetriableGcp(err: unknown): boolean {
  if (err instanceof HsmError) return false; // Already classified — don't retry
  if (!isGrpcError(err)) return false;
  return RETRIABLE_GRPC_CODES.has(err.code);
}

// ---------------------------------------------------------------------------
// Public configuration
// ---------------------------------------------------------------------------

export interface GcpKmsAdapterOptions {
  /**
   * Ordered list of GCP locations to try for region failover.
   * Each location replaces the `locations/{l}` segment in the key resource name.
   * Defaults to `["global"]`.
   *
   * Example: `["us-east1", "us-central1"]`
   */
  locations?: string[];

  /**
   * Optional factory for the KeyManagementServiceClient.
   * Used in tests to inject mock clients without real GCP credentials.
   */
  clientFactory?: (location?: string) => KeyManagementServiceClient;
}

// ---------------------------------------------------------------------------
// Helper: replace location in a GCP KMS resource name
// ---------------------------------------------------------------------------

function replaceLocation(resourceName: string, newLocation: string): string {
  // Resource names look like:
  //   projects/p/locations/us-east1/keyRings/kr/cryptoKeys/ck/cryptoKeyVersions/1
  return resourceName.replace(/\/locations\/[^/]+\//, `/locations/${newLocation}/`);
}

function extractParentKey(versionName: string): string {
  // Strip /cryptoKeyVersions/{v} to get the CryptoKey resource name
  const match = versionName.match(/^(.+\/cryptoKeys\/[^/]+)/);
  return match ? match[1] : versionName;
}

// ---------------------------------------------------------------------------
// Adapter
// ---------------------------------------------------------------------------

export class GcpKmsAdapter implements IHsmAdapter {
  private readonly locations: string[];
  private readonly clientFactory: (location?: string) => KeyManagementServiceClient;
  private readonly retry: RetryPolicy;

  constructor(options: GcpKmsAdapterOptions = {}) {
    this.locations = options.locations?.length ? options.locations : ["global"];
    this.clientFactory =
      options.clientFactory ?? (() => new KeyManagementServiceClient());
    this.retry = new RetryPolicy({
      ...DEFAULT_RETRY_CONFIG,
      maxRetries: 3,
      initialDelay: 200,
    });
  }

  // ──────────────────────────────────────────────────────────────────────────
  // sign
  // ──────────────────────────────────────────────────────────────────────────

  async sign(request: SignRequest): Promise<SignResponse> {
    if (!NODE_HASH_FOR_ALGORITHM[request.algorithm]) {
      throw new HsmError(
        `Unsupported algorithm: ${request.algorithm}`,
        "ALGORITHM_MISMATCH",
        { keyRef: request.key },
      );
    }

    const response = await this.withLocationFailover(request.key.keyId, async (keyId, client) => {
      return this.retry.execute(
        async () => {
          try {
            const [res] = await client.asymmetricSign({
              name: keyId,
              data: request.message,
            });
            return res;
          } catch (err) {
            if (isRetriableGcp(err)) throw err;
            throw classifyGcpError(err, keyId);
          }
        },
        (err) => isRetriableGcp(err),
      );
    });

    if (!response.signature) {
      throw new HsmError("GCP KMS returned empty signature", "PROVIDER_ERROR", {
        keyRef: request.key,
      });
    }

    return {
      signature: new Uint8Array(
        response.signature instanceof Uint8Array
          ? response.signature
          : Buffer.from(response.signature as string, "base64"),
      ),
      algorithm: request.algorithm,
      keyVersion: response.name ?? request.key.keyId,
    };
  }

  // ──────────────────────────────────────────────────────────────────────────
  // verify
  // ──────────────────────────────────────────────────────────────────────────

  /**
   * Verifies a signature by:
   * 1. Fetching the public key PEM from GCP KMS (getPublicKey)
   * 2. Verifying the signature locally using Node.js `crypto.createVerify`
   *
   * GCP Cloud KMS does not expose a server-side asymmetricVerify endpoint.
   */
  async verify(request: VerifyRequest): Promise<VerifyResponse> {
    const hashAlgorithm = NODE_HASH_FOR_ALGORITHM[request.algorithm];
    if (!hashAlgorithm) {
      throw new HsmError(
        `Unsupported algorithm: ${request.algorithm}`,
        "ALGORITHM_MISMATCH",
        { keyRef: request.key },
      );
    }

    // Retrieve the public key PEM from GCP KMS
    const publicKeyPem = await this.withLocationFailover(
      request.key.keyId,
      async (keyId, client) => {
        return this.retry.execute(
          async () => {
            try {
              const [pubKeyResponse] = await client.getPublicKey({ name: keyId });
              if (!pubKeyResponse.pem) {
                throw new HsmError("GCP KMS returned empty public key", "PROVIDER_ERROR");
              }
              return pubKeyResponse.pem;
            } catch (err) {
              if (err instanceof HsmError) throw err;
              if (isRetriableGcp(err)) throw err;
              throw classifyGcpError(err, keyId);
            }
          },
          (err) => isRetriableGcp(err),
        );
      },
    );

    // Verify locally using Node.js crypto
    try {
      const verifier = createVerify(hashAlgorithm);
      verifier.update(request.message);
      const valid = verifier.verify(
        publicKeyPem,
        Buffer.from(request.signature),
      );
      return {
        valid,
        keyVersion: request.key.keyId,
      };
    } catch {
      // Crypto verification errors (e.g. malformed signature) → not valid
      return { valid: false, keyVersion: request.key.keyId };
    }
  }

  // ──────────────────────────────────────────────────────────────────────────
  // rotate
  // ──────────────────────────────────────────────────────────────────────────

  async rotate(request: RotateRequest): Promise<RotateResponse> {
    const cryptoKeyName = extractParentKey(request.key.keyId);

    // 1. Find the current primary version before creating a new one
    const previousVersion = request.key.keyId.includes("/cryptoKeyVersions/")
      ? request.key.keyId
      : await this.withLocationFailover(cryptoKeyName, async (keyName, client) => {
          return this.retry.execute(
            async () => {
              try {
                const [key] = await client.getCryptoKey({ name: keyName });
                return key.primary?.name ?? keyName;
              } catch (err) {
                if (err instanceof HsmError) throw err;
                if (isRetriableGcp(err)) throw err;
                throw classifyGcpError(err, keyName);
              }
            },
            (err) => isRetriableGcp(err),
          );
        });

    // 2. Create a new key version
    const newVersionName = await this.withLocationFailover(
      cryptoKeyName,
      async (keyName, client) => {
        return this.retry.execute(
          async () => {
            try {
              const [newVersion] = await client.createCryptoKeyVersion({
                parent: keyName,
                cryptoKeyVersion: {},
              });
              return newVersion.name ?? keyName;
            } catch (err) {
              if (err instanceof HsmError) throw err;
              if (isRetriableGcp(err)) throw err;
              throw classifyGcpError(err, keyName);
            }
          },
          (err) => isRetriableGcp(err),
        );
      },
    );

    // 3. Schedule the previous version for destruction (non-fatal)
    if (previousVersion !== cryptoKeyName) {
      try {
        await this.withLocationFailover(previousVersion, async (versionName, client) => {
          return this.retry.execute(
            async () => {
              try {
                await client.destroyCryptoKeyVersion({ name: versionName });
              } catch (err) {
                if (err instanceof HsmError) throw err;
                if (isRetriableGcp(err)) throw err;
                throw classifyGcpError(err, versionName);
              }
            },
            (err) => isRetriableGcp(err),
          );
        });
      } catch {
        // Non-fatal: destroy failure is swallowed.
        // In production this would emit a metric/alert.
      }
    }

    return {
      newKeyVersion: newVersionName,
      previousKeyVersion: previousVersion,
    };
  }

  // ──────────────────────────────────────────────────────────────────────────
  // Location failover helper
  // ──────────────────────────────────────────────────────────────────────────

  private async withLocationFailover<T>(
    keyId: string,
    fn: (resolvedKeyId: string, client: KeyManagementServiceClient) => Promise<T>,
  ): Promise<T> {
    let lastError: HsmError | undefined;

    for (let i = 0; i < this.locations.length; i++) {
      const location = this.locations[i];
      // For the first location use the keyId as-is; for subsequent locations
      // rewrite the location segment.
      const resolvedKeyId =
        i === 0 ? keyId : replaceLocation(keyId, location);

      const client = this.clientFactory(location);
      try {
        return await fn(resolvedKeyId, client);
      } catch (err) {
        if (err instanceof HsmError) {
          // Structural errors (not-found, permission) don't benefit from failover
          if (
            err.code === "KEY_NOT_FOUND" ||
            err.code === "PERMISSION_DENIED" ||
            err.code === "ALGORITHM_MISMATCH" ||
            err.code === "KEY_DISABLED"
          ) {
            throw err;
          }
          lastError = err;
          continue;
        }
        // Unexpected non-HsmError — classify and fail without failover
        throw classifyGcpError(err, keyId);
      }
    }

    throw (
      lastError ??
      new HsmError("All GCP locations exhausted", "REGION_UNAVAILABLE")
    );
  }
}

// @ts-nocheck
// rrule is a CJS module; import the default export and destructure for
// compatibility with Jest's --experimental-vm-modules ESM test environment.
import * as rruleLib from "rrule";
import type { RRule as RRuleType } from "rrule";
import rruleLib from "rrule";
import { AuditLogger, defaultAuditLogger } from "./auditLogger.js";
import { SupplierTimezoneContext } from "../modules/slots/slot-repository.js";
import {
  TimezoneResolverService,
  createInMemoryTimezoneResolverDeps,
} from "./timezoneResolverService.js";
const { RRule: _RRule, rrulestr } = rruleLib as any as {
  RRule: typeof RRuleType;
  rrulestr: (rruleStr: string, options?: Record<string, unknown>) => RRuleType;
};

export const MAX_OCCURRENCES = 200;

/** Maximum number of EXDATE entries allowed in a single rule string. */
export const MAX_EXDATES = 100;

export class RecurrenceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RecurrenceError";
  }
}

/**
 * A blackout window: any RRULE occurrence that falls within [startMs, endMs]
 * (inclusive) is suppressed from the final expansion.
 */
export interface BlackoutWindow {
  /** Inclusive start of the blackout period in epoch milliseconds. */
  startMs: number;
  /** Inclusive end of the blackout period in epoch milliseconds. */
  endMs: number;
  /** Optional human-readable label (e.g., "Company shutdown Q4"). */
  label?: string;
}

/**
 * Result of {@link expandRRuleWithExdate}, detailing which occurrences were
 * removed and why.
 */
export interface ExpandRRuleResult {
  /** Occurrences remaining after all exclusions (EXDATE + blackouts). */
  occurrences: Date[];
  /** Dates excluded by EXDATE directives (at day granularity, UTC). */
  excludedByExdate: Date[];
  /** Dates excluded by blackout windows. */
  excludedByBlackout: Date[];
}

// ─── EXDATE parsing ───────────────────────────────────────────────────────────

/**
 * Extract EXDATE values from an iCalendar text block.
 *
 * Supports:
 *  - `EXDATE:20260101T000000Z,20260201T000000Z`  (comma-separated UTC)
 *  - `EXDATE;TZID=America/New_York:20260101T090000` (TZID parameter)
 *  - Multiple EXDATE lines
 *  - DATE-only values: `EXDATE:20260101`
 *
 * Returns an array of UTC Date objects normalised to midnight UTC of the
 * excluded day (so the comparison in {@link expandRRuleWithExdate} only
 * needs day-level equality regardless of the time component in the rule).
 *
 * @throws RecurrenceError if the value list exceeds MAX_EXDATES.
 */
export function parseExdates(rruleText: string): Date[] {
  const exdates: Date[] = [];

  // Each EXDATE property may contain multiple comma-separated values.
  // Pattern: EXDATE[;param=value]*:<value-list>
  const exdateLineRegex = /^EXDATE(?:;[^:]*)?:(.+)$/gim;
  let match: RegExpExecArray | null;

  while ((match = exdateLineRegex.exec(rruleText)) !== null) {
    const valueList = match[1].trim();
    const values = valueList.split(",").map((v) => v.trim()).filter(Boolean);
    for (const val of values) {
      const d = parseSingleExdate(val);
      if (d) exdates.push(d);
    }
  }

  if (exdates.length > MAX_EXDATES) {
    throw new RecurrenceError(
      `EXDATE list exceeds maximum of ${MAX_EXDATES} entries`,
    );
  }

  return exdates;
}

/**
 * Parse a single iCalendar date-time value (e.g., `20260701T120000Z`,
 * `20260701T120000`, `20260701`) into a UTC Date at midnight of that day.
 * Returns null for unrecognised formats so the caller can skip them.
 */
function parseSingleExdate(value: string): Date | null {
  // Strip any trailing 'Z' for normalisation; we always treat as day-level.
  const v = value.replace(/Z$/i, "").trim();
  // DATE-TIME: YYYYMMDDTHHMMSS
  const dtMatch = v.match(/^(\d{4})(\d{2})(\d{2})T\d{6}/);
  // DATE: YYYYMMDD
  const dateMatch = v.match(/^(\d{4})(\d{2})(\d{2})$/);

  const m = dtMatch ?? dateMatch;
  if (!m) return null;

  const year = parseInt(m[1], 10);
  const month = parseInt(m[2], 10) - 1; // 0-indexed
  const day = parseInt(m[3], 10);

  // Normalise to midnight UTC so we can compare at day granularity.
  return new Date(Date.UTC(year, month, day, 0, 0, 0, 0));
}

/**
 * Returns true when two dates represent the same UTC calendar day.
 */
function sameUtcDay(a: Date, b: Date): boolean {
  return (
    a.getUTCFullYear() === b.getUTCFullYear() &&
    a.getUTCMonth() === b.getUTCMonth() &&
    a.getUTCDate() === b.getUTCDate()
  );
}

// ─── Core expansion ───────────────────────────────────────────────────────────

/**
 * Expand an iCalendar RRULE string into concrete occurrences, applying both
 * EXDATE exclusions (parsed from the text) and explicit blackout windows.
 *
 * Blackouts and EXDATEs are additive: an occurrence is excluded if it falls
 * within *either* an EXDATE or *any* overlapping blackout window.
 *
 * @param rruleText  Full iCalendar text; may include DTSTART, RRULE, EXDATE lines.
 * @param blackouts  Optional array of blackout windows.
 * @returns          {@link ExpandRRuleResult} with separated exclusion sets.
 *
 * @throws RecurrenceError for invalid/unbounded rules or oversized EXDATE lists.
 */
export function expandRRuleWithExdate(
  rruleText: string,
  blackouts: BlackoutWindow[] = [],
): ExpandRRuleResult {
  if (typeof rruleText !== "string" || rruleText.trim().length === 0) {
    throw new RecurrenceError("rrule must be a non-empty string");
  }

  // Parse EXDATE lines before we pass the text to rrulestr (rrule.js ignores
  // unknown lines, so we extract them ourselves).
  const exdates = parseExdates(rruleText);

  // Build a version of the text without EXDATE lines so that rrulestr
  // processes only the RRULE/DTSTART/RDATE content.
  const rruleOnly = rruleText
    .split(/\r?\n/)
    .filter((line) => !/^EXDATE/i.test(line.trim()))
    .join("\n");

  let rule: RRuleType;
  try {
    rule = rrulestr(rruleOnly, { forceset: false }) as unknown as RRuleType;
  } catch {
    throw new RecurrenceError("Invalid RRULE format");
  }

  const options = (rule as any).options;
  if ((options.count ?? 0) <= 0 && !options.until) {
    throw new RecurrenceError("Unbounded RRULE is not allowed; include COUNT or UNTIL");
  }
  if (options.interval !== undefined && options.interval < 1 || /(?:^|[;\n])INTERVAL=-?[0]+(?:;|$)/i.test(rruleText)) {
    throw new RecurrenceError("INTERVAL must be a positive integer");
  }

  const rawOccurrences: Date[] = (rule as any).all(
    (_occ: Date, i: number) => i < MAX_OCCURRENCES + 1,
  );
  if (rawOccurrences.length > MAX_OCCURRENCES) {
    throw new RecurrenceError(
      `RRULE expands to more than ${MAX_OCCURRENCES} occurrences`,
    );
  }

  const excludedByExdate: Date[] = [];
  const excludedByBlackout: Date[] = [];
  const occurrences: Date[] = [];

  for (const occ of rawOccurrences) {
    const occMs = occ.getTime();

    // EXDATE check (day-level UTC comparison)
    if (exdates.some((ex) => sameUtcDay(ex, occ))) {
      excludedByExdate.push(occ);
      continue;
    }

    // Blackout check (ms-level range comparison)
    const inBlackout = blackouts.some((b) => occMs >= b.startMs && occMs <= b.endMs);
    if (inBlackout) {
      excludedByBlackout.push(occ);
      continue;
    }

    occurrences.push(occ);
  }

  return { occurrences, excludedByExdate, excludedByBlackout };
}

/**
 * Backward-compatible wrapper around {@link expandRRuleWithExdate}.
 *
 * If the input text contains EXDATE lines they are silently applied, so
 * existing callers that do not need the detailed exclusion report can continue
 * to use this function unchanged.
 *
 * @param rruleText  iCalendar text (may include EXDATE lines).
 * @param _dtstartIso  Unused; retained for API compatibility.
 */
export function expandRRule(rruleText: string, _dtstartIso?: string): Date[] {
  return expandRRuleWithExdate(rruleText).occurrences;
}

export interface RegionalHoliday {
  date: string;
  name: string;
  regionCodes: string[];
  observanceType: "full_day" | "half_day" | "morning" | "afternoon" | "bank_holiday";
  isSuppressedByDefault?: boolean;
  notes?: string;
}

export interface HolidayImpact {
  occurrence: {
    dateIso: string;
    timestampMs: number;
  };
  holiday: RegionalHoliday;
  affectedRegionCodes: string[];
  resolutionHint: "suppress" | "flag_only" | "adjust_hours";
}

export interface HolidayImpactAnalysis {
  totalOccurrences: number;
  affectedOccurrences: number;
  impactedOccurrences: HolidayImpact[];
  uniqueRegionCodes: string[];
  uniqueHolidayNames: string[];
  summary: string;
  analysisGeneratedAt: string;
  scope: {
    supplierId?: string;
    storeId?: string;
    regionCodesScoped: string[];
  };
}

export interface HolidayRegistry {
  listHolidaysInRange(startMs: number, endMs: number, regionCodes?: string[]): Promise<RegionalHoliday[]>;
  listHolidaysInRangeSync(startMs: number, endMs: number, regionCodes?: string[]): RegionalHoliday[];
}

export function createInMemoryHolidayRegistry(seed: RegionalHoliday[] = []): HolidayRegistry {
  const holidays = [...seed];
  const matchesRegion = (h: RegionalHoliday, filter: string[] | undefined): boolean => {
    if (!filter || filter.length === 0) return true;
    return h.regionCodes.some((r) => filter.includes(r));
  };
  const inRange = (h: RegionalHoliday, startMs: number, endMs: number): boolean => {
    const dayMs = new Date(h.date + "T00:00:00Z").getTime();
    const dayEndMs = dayMs + 24 * 60 * 60 * 1000 - 1;
    return dayEndMs >= startMs && dayMs <= endMs;
  };
  const query = (startMs: number, endMs: number, regionCodes?: string[]) =>
    holidays
      .filter((h) => inRange(h, startMs, endMs))
      .filter((h) => matchesRegion(h, regionCodes));
  return {
    listHolidaysInRange: async (s, e, r) => query(s, e, r),
    listHolidaysInRangeSync: (s, e, r) => query(s, e, r),
  };
}

function sameDayIso(aIso: string, occurrenceMs: number, resolvedTimezone: string): boolean {
  const aDate = new Date(aIso + "T00:00:00Z");
  const aDay = formatDateInTimezone(aDate.getTime(), resolvedTimezone);
  const oDay = formatDateInTimezone(occurrenceMs, resolvedTimezone);
  return aDay === oDay;
}

function formatDateInTimezone(epochMs: number, ianaTimezone: string): string {
  try {
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone: ianaTimezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    const parts = formatter.formatToParts(new Date(epochMs));
    const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
    return `${get("year")}-${get("month")}-${get("day")}`;
  } catch {
    const d = new Date(epochMs);
    const pad = (n: number) => String(n).padStart(2, "0");
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  }
}

function pickResolutionHint(holiday: RegionalHoliday): HolidayImpact["resolutionHint"] {
  if (holiday.isSuppressedByDefault) return "suppress";
  if (holiday.observanceType === "bank_holiday") return "suppress";
  if (holiday.observanceType === "half_day" || holiday.observanceType === "morning" || holiday.observanceType === "afternoon") {
    return "adjust_hours";
  }
  return "flag_only";
}

export interface HolidayImpactAnalyzerDeps {
  holidayRegistry?: HolidayRegistry;
  auditLogger?: AuditLogger;
  getSupplierContext?: (supplierId: string) => Promise<SupplierTimezoneContext | undefined>;
  timezoneResolver?: TimezoneResolverService;
  nowIso?: () => string;
}

export class HolidayImpactAnalyzer {
  private readonly holidayRegistry: HolidayRegistry;
  private readonly auditLogger: AuditLogger;
  private readonly getSupplierContext: (supplierId: string) => Promise<SupplierTimezoneContext | undefined>;
  private readonly timezoneResolver: TimezoneResolverService;
  private readonly nowIso: () => string;

  constructor(deps: HolidayImpactAnalyzerDeps = {}) {
    this.holidayRegistry = deps.holidayRegistry ?? createInMemoryHolidayRegistry();
    this.auditLogger = deps.auditLogger ?? defaultAuditLogger;
    const tzDeps = createInMemoryTimezoneResolverDeps({ auditLogger: this.auditLogger });
    this.getSupplierContext = deps.getSupplierContext ?? tzDeps.getSupplierContext;
    this.timezoneResolver =
      deps.timezoneResolver ?? new TimezoneResolverService(tzDeps);
    this.nowIso = deps.nowIso ?? (() => new Date().toISOString());
  }

  async analyze(params: {
    rruleText: string;
    supplierId?: string;
    storeId?: string;
    tenantId?: string;
    scopedRegionCodes?: string[];
    actorId?: string;
    /** Optional blackout windows to suppress from the expansion (stacks with EXDATE). */
    blackouts?: BlackoutWindow[];
  }): Promise<HolidayImpactAnalysis> {
    const { rruleText, supplierId, storeId, tenantId, scopedRegionCodes, actorId, blackouts } = params;

    const occurrences = expandRRuleWithExdate(rruleText, blackouts ?? []).occurrences;
    if (occurrences.length === 0) {
      return this.emptyAnalysis(supplierId, storeId, scopedRegionCodes);
    }

    const startMs = occurrences[0].getTime();
    const endMs = occurrences[occurrences.length - 1].getTime();

    let effectiveRegions: string[] = [];
    let resolvedTimezone = "UTC";

    if (supplierId) {
      const supplierCtx = await this.getSupplierContext(supplierId);
      if (supplierCtx) {
        const directStoreRegions = this.timezoneResolver.getRegionsForStore({
          supplierContext: supplierCtx,
          storeId,
        });
        const supplierAllRegions = this.timezoneResolver.getAllRegionsForSupplier(supplierCtx);
        const baseRegions = (storeId ? directStoreRegions : supplierAllRegions) || [];
        effectiveRegions = baseRegions;

        if (tenantId) {
          try {
            const tzResult = await this.timezoneResolver.resolveTimezone({
              supplierId,
              tenantId,
              storeId,
              actorId,
            });
            resolvedTimezone = tzResult.timezone;
          } catch {
            resolvedTimezone = "UTC";
          }
        }
      }
    }

    if (scopedRegionCodes && scopedRegionCodes.length > 0) {
      effectiveRegions =
        effectiveRegions.length > 0
          ? effectiveRegions.filter((r) => scopedRegionCodes.includes(r))
          : scopedRegionCodes;
    }

    const holidays = await this.holidayRegistry.listHolidaysInRange(
      startMs,
      endMs,
      effectiveRegions.length > 0 ? effectiveRegions : undefined,
    );

    const impacts: HolidayImpact[] = [];
    const uniqueRegions = new Set<string>();
    const uniqueHolidays = new Set<string>();

    for (const occ of occurrences) {
      const occMs = occ.getTime();
      for (const holiday of holidays) {
        const affectedRegions =
          effectiveRegions.length > 0
            ? holiday.regionCodes.filter((r) => effectiveRegions.includes(r))
            : holiday.regionCodes;
        if (affectedRegions.length === 0) continue;
        if (!sameDayIso(holiday.date, occMs, resolvedTimezone)) continue;

        for (const r of affectedRegions) uniqueRegions.add(r);
        uniqueHolidays.add(holiday.name);

        impacts.push({
          occurrence: {
            dateIso: formatDateInTimezone(occMs, resolvedTimezone),
            timestampMs: occMs,
          },
          holiday,
          affectedRegionCodes: affectedRegions,
          resolutionHint: pickResolutionHint(holiday),
        });
      }
    }

    const uniqueRegionCodes = Array.from(uniqueRegions).sort();
    const uniqueHolidayNames = Array.from(uniqueHolidays).sort();
    const summary = this.buildSummary(
      occurrences.length,
      impacts.length,
      uniqueHolidayNames,
      uniqueRegionCodes,
    );

    const analysis: HolidayImpactAnalysis = {
      totalOccurrences: occurrences.length,
      affectedOccurrences: impacts.length,
      impactedOccurrences: impacts,
      uniqueRegionCodes,
      uniqueHolidayNames,
      summary,
      analysisGeneratedAt: this.nowIso(),
      scope: {
        supplierId,
        storeId,
        regionCodesScoped: effectiveRegions,
      },
    };

    await this.auditLogger.log("recurrence.holiday_impact_analyzed", {
      context: {
        supplierId,
        storeId,
        totalOccurrences: analysis.totalOccurrences,
        affectedOccurrences: analysis.affectedOccurrences,
        uniqueHolidayNames,
        uniqueRegionCodes,
      },
      userId: actorId,
    }, {
      resource: supplierId ? `supplier:${supplierId}${storeId ? `:store:${storeId}` : ""}` : "recurrence-analysis",
      status: 200,
    });

    return analysis;
  }

  analyzeSync(params: {
    rruleText: string;
    supplierContext?: SupplierTimezoneContext;
    storeId?: string;
    resolvedTimezone?: string;
    scopedRegionCodes?: string[];
    holidays: RegionalHoliday[];
    /** Optional blackout windows to suppress from the expansion (stacks with EXDATE). */
    blackouts?: BlackoutWindow[];
  }): HolidayImpactAnalysis {
    const { rruleText, supplierContext, storeId, resolvedTimezone, scopedRegionCodes, holidays, blackouts } = params;

    const occurrences = expandRRuleWithExdate(rruleText, blackouts ?? []).occurrences;
    if (occurrences.length === 0) {
      return this.emptyAnalysis(
        supplierContext?.supplierId,
        storeId,
        scopedRegionCodes,
      );
    }

    const startMs = occurrences[0].getTime();
    const endMs = occurrences[occurrences.length - 1].getTime();

    const tz = resolvedTimezone ?? "UTC";
    const directStoreRegions = this.timezoneResolver.getRegionsForStore({
      supplierContext,
      storeId,
    });
    const supplierAllRegions = this.timezoneResolver.getAllRegionsForSupplier(supplierContext);
    let effectiveRegions = (storeId ? directStoreRegions : supplierAllRegions) || [];
    if (scopedRegionCodes && scopedRegionCodes.length > 0) {
      effectiveRegions =
        effectiveRegions.length > 0
          ? effectiveRegions.filter((r) => scopedRegionCodes.includes(r))
          : scopedRegionCodes;
    }

    const rangeHolidays = holidays.filter((h) => {
      const dayMs = new Date(h.date + "T00:00:00Z").getTime();
      const dayEndMs = dayMs + 24 * 60 * 60 * 1000 - 1;
      return dayEndMs >= startMs && dayMs <= endMs;
    });

    const impacts: HolidayImpact[] = [];
    const uniqueRegions = new Set<string>();
    const uniqueHolidays = new Set<string>();

    for (const occ of occurrences) {
      const occMs = occ.getTime();
      for (const holiday of rangeHolidays) {
        const affectedRegions =
          effectiveRegions.length > 0
            ? holiday.regionCodes.filter((r) => effectiveRegions.includes(r))
            : holiday.regionCodes;
        if (affectedRegions.length === 0) continue;
        if (!sameDayIso(holiday.date, occMs, tz)) continue;

        for (const r of affectedRegions) uniqueRegions.add(r);
        uniqueHolidays.add(holiday.name);

        impacts.push({
          occurrence: {
            dateIso: formatDateInTimezone(occMs, tz),
            timestampMs: occMs,
          },
          holiday,
          affectedRegionCodes: affectedRegions,
          resolutionHint: pickResolutionHint(holiday),
        });
      }
    }

    const uniqueRegionCodes = Array.from(uniqueRegions).sort();
    const uniqueHolidayNames = Array.from(uniqueHolidays).sort();
    const summary = this.buildSummary(
      occurrences.length,
      impacts.length,
      uniqueHolidayNames,
      uniqueRegionCodes,
    );

    return {
      totalOccurrences: occurrences.length,
      affectedOccurrences: impacts.length,
      impactedOccurrences: impacts,
      uniqueRegionCodes,
      uniqueHolidayNames,
      summary,
      analysisGeneratedAt: this.nowIso(),
      scope: {
        supplierId: supplierContext?.supplierId,
        storeId,
        regionCodesScoped: effectiveRegions,
      },
    };
  }

  private emptyAnalysis(
    supplierId?: string,
    storeId?: string,
    scopedRegionCodes?: string[],
  ): HolidayImpactAnalysis {
    return {
      totalOccurrences: 0,
      affectedOccurrences: 0,
      impactedOccurrences: [],
      uniqueRegionCodes: [],
      uniqueHolidayNames: [],
      summary: "No occurrences generated by the RRULE.",
      analysisGeneratedAt: this.nowIso(),
      scope: {
        supplierId,
        storeId,
        regionCodesScoped: scopedRegionCodes ?? [],
      },
    };
  }

  private buildSummary(
    total: number,
    affected: number,
    holidayNames: string[],
    regionCodes: string[],
  ): string {
    if (total === 0) return "No occurrences generated by the RRULE.";
    if (affected === 0) return `All ${total} occurrence(s) are clear of regional holidays in the scoped regions.`;
    const pct = Math.round((affected / total) * 100);
    const holidayStr = holidayNames.length > 0 ? ` (${holidayNames.join(", ")})` : "";
    const regionStr = regionCodes.length > 0 ? ` in ${regionCodes.length} region(s)` : "";
    return `${affected} of ${total} occurrence(s) (${pct}%) intersect${holidayStr.length > 1 ? "" : "s"} with${holidayStr}${regionStr}.`;
  }
}

export function groupImpactsByHoliday(analysis: HolidayImpactAnalysis): Record<string, HolidayImpact[]> {
  const grouped: Record<string, HolidayImpact[]> = {};
  for (const impact of analysis.impactedOccurrences) {
    const key = impact.holiday.name;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(impact);
  }
  return grouped;
}

export function groupImpactsByDate(analysis: HolidayImpactAnalysis): Record<string, HolidayImpact[]> {
  const grouped: Record<string, HolidayImpact[]> = {};
  for (const impact of analysis.impactedOccurrences) {
    const key = impact.occurrence.dateIso;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(impact);
  }
  return grouped;
}
